guard_homework_assignment_immutables.body:
CREATE OR REPLACE FUNCTION public.guard_homework_assignment_immutables()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF public.has_role(auth.uid(), 'admin') THEN
    RETURN NEW;
  END IF;

  IF NEW.set_id           IS DISTINCT FROM OLD.set_id           OR
     NEW.student_id       IS DISTINCT FROM OLD.student_id       OR
     NEW.question_qids    IS DISTINCT FROM OLD.question_qids    OR
     NEW.set_title        IS DISTINCT FROM OLD.set_title        OR
     NEW.set_description  IS DISTINCT FROM OLD.set_description  OR
     NEW.assigned_by      IS DISTINCT FROM OLD.assigned_by      OR
     NEW.class_id         IS DISTINCT FROM OLD.class_id         OR
     NEW.created_at       IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'homework_assignments: snapshot columns are immutable for non-admin users';
  END IF;

  RETURN NEW;
END;
$$

guard_notification_immutables.body:
create or replace function public.guard_notification_immutables()
returns trigger language plpgsql as $$
begin
  if public.has_role(auth.uid(), 'admin') then
    return new;
  end if;
  if new.user_id    is distinct from old.user_id    or
     new.type       is distinct from old.type       or
     new.title      is distinct from old.title      or
     new.body       is distinct from old.body       or
     new.link       is distinct from old.link       or
     new.created_at is distinct from old.created_at then
    raise exception 'notifications: only the read flag is mutable for non-admin users';
  end if;
  if old.read = true and new.read = false then
    raise exception 'notifications: read flag cannot be flipped back to false';
  end if;
  return new;
end;
$$

get_or_create_joshua_conversation.body:
CREATE OR REPLACE FUNCTION public.get_or_create_joshua_conversation()
RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  _student uuid := auth.uid();
  _admin   uuid;
  _conv    uuid;
BEGIN
  IF _student IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;

  SELECT user_id INTO _admin
    FROM public.user_roles WHERE role = 'admin'
    ORDER BY user_id LIMIT 1;
  IF _admin IS NULL THEN RAISE EXCEPTION 'no admin configured'; END IF;

  SELECT cp1.conversation_id INTO _conv
  FROM public.conversation_participants cp1
  JOIN public.conversation_participants cp2
    ON cp2.conversation_id = cp1.conversation_id
  WHERE cp1.user_id = _student AND cp2.user_id = _admin
  LIMIT 1;

  IF _conv IS NOT NULL THEN
    RETURN _conv::text;
  END IF;

  INSERT INTO public.conversations (created_by) VALUES (_admin) RETURNING id INTO _conv;
  INSERT INTO public.conversation_participants (conversation_id, user_id)
    VALUES (_conv, _admin), (_conv, _student);

  RETURN _conv::text;
END;
$$

notify_admins_on_signup.body:
CREATE OR REPLACE FUNCTION public.notify_admins_on_signup()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  admin_id uuid;
  who text;
  subject_email text;
BEGIN
  BEGIN
    SELECT u.email INTO subject_email
    FROM auth.users u
    WHERE u.id = NEW.class_id::uuid;
  EXCEPTION WHEN others THEN
    subject_email := NULL;
  END;

  who := COALESCE(
    NULLIF(NEW.display_name, ''),
    NULLIF(subject_email, ''),
    'A new user'
  );

  FOR admin_id IN SELECT user_id FROM public.user_roles WHERE role = 'admin' LOOP
    INSERT INTO public.notifications (
      user_id,
      type,
      title,
      body,
      link,
      subject_class_id,
      status
    )
    VALUES (
      admin_id,
      'signup',
      'New signup',
      who || ' just signed up and is waiting for access.',
      '/teacher/students',
      NEW.class_id,
      'pending'
    );
  END LOOP;

  RETURN NEW;
END;
$$

