create or replace function public.get_or_create_personal_plan(p_student uuid)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_id uuid;
begin
  if p_student is null then
    raise exception 'p_student is required';
  end if;

  select id into v_id
  from public.weekly_plans
  where student_id = p_student and title = '__personal__'
  limit 1;

  if v_id is null then
    insert into public.weekly_plans (
      student_id, created_by, title, week_start, week_end, status, ai_generated
    ) values (
      p_student, p_student, '__personal__',
      '2000-01-01'::date, '2999-12-31'::date, 'published', false
    )
    returning id into v_id;
  end if;

  return v_id;
end;
$$

redeem_booking_pass.body:
CREATE OR REPLACE FUNCTION public.redeem_booking_pass(_pass_id uuid, _idempotency_key text, _start_at timestamp with time zone, _end_at timestamp with time zone, _schedule_event_id uuid, _google_event_id text, _student_name text, _student_email text)
 RETURNS TABLE(redemption_id uuid, used_credits integer, total_credits integer, status text, was_existing boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _pass public.booking_passes%ROWTYPE;
  _existing public.booking_pass_redemptions%ROWTYPE;
  _new_id uuid;
  _conflict_count int;
BEGIN
  SELECT * INTO _existing FROM public.booking_pass_redemptions bpr
   WHERE bpr.booking_pass_id = _pass_id AND bpr.idempotency_key = _idempotency_key;
  IF FOUND THEN
    SELECT * INTO _pass FROM public.booking_passes bp WHERE bp.id = _pass_id;
    redeem_booking_pass.redemption_id := _existing.id;
    redeem_booking_pass.used_credits := _pass.used_credits;
    redeem_booking_pass.total_credits := _pass.total_credits;
    redeem_booking_pass.status := _pass.status;
    redeem_booking_pass.was_existing := true;
    RETURN NEXT;
    RETURN;
  END IF;

  SELECT * INTO _pass FROM public.booking_passes bp WHERE bp.id = _pass_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'pass_not_found';
  END IF;
  IF _pass.status <> 'active' THEN
    RAISE EXCEPTION 'pass_not_active:%', _pass.status;
  END IF;
  IF _pass.expires_at IS NOT NULL AND _pass.expires_at < now() THEN
    UPDATE public.booking_passes bp SET status = 'expired' WHERE bp.id = _pass_id;
    RAISE EXCEPTION 'pass_expired';
  END IF;
  IF _pass.used_credits >= _pass.total_credits THEN
    UPDATE public.booking_passes bp SET status = 'exhausted' WHERE bp.id = _pass_id;
    RAISE EXCEPTION 'pass_exhausted';
  END IF;

  SELECT COUNT(*) INTO _conflict_count
    FROM public.schedule_events se
   WHERE se.deleted_at IS NULL
     AND se.status <> 'cancelled'
     AND (_schedule_event_id IS NULL OR se.id <> _schedule_event_id)
     AND se.start_at < _end_at
     AND se.end_at > _start_at;
  IF _conflict_count > 0 THEN
    RAISE EXCEPTION 'slot_conflict';
  END IF;

  INSERT INTO public.booking_pass_redemptions
    (booking_pass_id, schedule_event_id, google_event_id, start_at, end_at,
     status, idempotency_key, student_name_snapshot, student_email_snapshot)
  VALUES (_pass_id, _schedule_event_id, _google_event_id, _start_at, _end_at,
          'booked', _idempotency_key, _student_name, _student_email)
  RETURNING id INTO _new_id;

  UPDATE public.booking_passes bp
     SET used_credits = bp.used_credits + 1,
         status = CASE WHEN bp.used_credits + 1 >= bp.total_credits THEN 'exhausted' ELSE 'active' END
   WHERE bp.id = _pass_id
   RETURNING bp.* INTO _pass;

  redeem_booking_pass.redemption_id := _new_id;
  redeem_booking_pass.used_credits := _pass.used_credits;
  redeem_booking_pass.total_credits := _pass.total_credits;
  redeem_booking_pass.status := _pass.status;
  redeem_booking_pass.was_existing := false;
  RETURN NEXT;
END;
$function$

promote_lsat_knowledge_version.body:
CREATE OR REPLACE FUNCTION public.promote_lsat_knowledge_version(
  _slug text,
  _version text,
  _expected_count integer
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _staged_total int;
  _staged_slug int;
  _no_embed int;
  _bad_dim int;
  _prev_active text;
  _obsolete int := 0;
  _inserted int := 0;
BEGIN
  -- Lock the source row to serialize concurrent promotions.
  PERFORM 1 FROM lsat_knowledge_sources
    WHERE slug = _slug AND version = _version
    FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'source_row_missing: %/%', _slug, _version;
  END IF;

  SELECT count(*) INTO _staged_total
    FROM lsatu_content_staging
   WHERE import_version = _version;
  SELECT count(*) INTO _staged_slug
    FROM lsatu_content_staging
   WHERE import_version = _version
     AND kind = 'lsat_methodology'
     AND metadata->>'source_slug' = _slug;

  IF _staged_slug <> _expected_count THEN
    RAISE EXCEPTION 'staged_count_mismatch: got % expected %', _staged_slug, _expected_count;
  END IF;
  IF _staged_total <> _staged_slug THEN
    RAISE EXCEPTION 'staging_polluted: total % vs slug %', _staged_total, _staged_slug;
  END IF;

  SELECT count(*) INTO _no_embed
    FROM lsatu_content_staging
   WHERE import_version = _version AND embedding IS NULL;
  IF _no_embed > 0 THEN
    RAISE EXCEPTION 'missing_embeddings: %', _no_embed;
  END IF;

  SELECT count(*) INTO _bad_dim
    FROM lsatu_content_staging
   WHERE import_version = _version
     AND vector_dims(embedding) <> 3072;
  IF _bad_dim > 0 THEN
    RAISE EXCEPTION 'wrong_dim: %', _bad_dim;
  END IF;

  SELECT version INTO _prev_active
    FROM lsat_knowledge_sources
   WHERE slug = _slug AND status = 'active' AND version <> _version
   LIMIT 1;

  -- Archive any currently-active version(s) for this slug (other than us).
  UPDATE lsat_knowledge_sources
     SET status = 'archived', updated_at = now()
   WHERE slug = _slug AND status = 'active' AND version <> _version;

  -- Remove old live records for this slug (any prior version). Counted for reporting.
  WITH del AS (
    DELETE FROM lsatu_content_index
     WHERE kind = 'lsat_methodology'
       AND metadata->>'source_slug' = _slug
    RETURNING 1
  )
  SELECT count(*) INTO _obsolete FROM del;

  -- Promote staged rows into live index.
  WITH ins AS (
    INSERT INTO lsatu_content_index
      (kind, source_id, chunk_index, title, subtitle, body, url, metadata, embedding)
    SELECT kind, source_id, chunk_index, title, subtitle, body, url, metadata, embedding
      FROM lsatu_content_staging
     WHERE import_version = _version
       AND metadata->>'source_slug' = _slug
    RETURNING 1
  )
  SELECT count(*) INTO _inserted FROM ins;

  IF _inserted <> _expected_count THEN
    -- Trigger rollback of the whole transaction.
    RAISE EXCEPTION 'insert_count_mismatch: inserted % expected %', _inserted, _expected_count;
  END IF;

  -- Flip source row to active.
  UPDATE lsat_knowledge_sources
     SET status = 'active', updated_at = now()
   WHERE slug = _slug AND version = _version;

  -- Clear staging for this version.
  DELETE FROM lsatu_content_staging WHERE import_version = _version;

  RETURN jsonb_build_object(
    'promoted', _inserted,
    'obsolete_removed', _obsolete,
    'previously_active_version', _prev_active
  );
END;
$$

set_booking_availability.body:
CREATE OR REPLACE FUNCTION public.set_booking_availability(_timezone text, _ranges jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _overlap boolean;
BEGIN
  IF _timezone IS NOT NULL AND length(_timezone) > 0 THEN
    PERFORM now() AT TIME ZONE _timezone;
  END IF;

  WITH parsed AS (
    SELECT (e->>'day_of_week')::int AS dow,
      (e->>'start_time')::time AS start_time,
      (e->>'end_time')::time AS end_time
    FROM jsonb_array_elements(COALESCE(_ranges, '[]'::jsonb)) e
  )
  SELECT EXISTS (
    SELECT 1 FROM parsed a JOIN parsed b
      ON a.dow = b.dow
      AND (a.start_time, a.end_time) <> (b.start_time, b.end_time)
      AND a.start_time < b.end_time AND a.end_time > b.start_time
  ) INTO _overlap;
  IF _overlap THEN
    RAISE EXCEPTION 'overlapping_availability_ranges' USING ERRCODE = 'P0400';
  END IF;

  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(COALESCE(_ranges, '[]'::jsonb)) e
    WHERE (e->>'day_of_week')::int NOT BETWEEN 0 AND 6
      OR (e->>'end_time')::time <= (e->>'start_time')::time
  ) THEN
    RAISE EXCEPTION 'invalid_availability_range' USING ERRCODE = 'P0400';
  END IF;

  IF _timezone IS NOT NULL AND length(_timezone) > 0 THEN
    UPDATE public.booking_availability_config
    SET timezone = _timezone, updated_at = now() WHERE id = 1;
  END IF;

  DELETE FROM public.booking_availability;
  INSERT INTO public.booking_availability(day_of_week, start_time, end_time)
  SELECT (e->>'day_of_week')::int, (e->>'start_time')::time, (e->>'end_time')::time
  FROM jsonb_array_elements(COALESCE(_ranges, '[]'::jsonb)) e;

  RETURN public.get_booking_availability();
END;
$$

is_slot_bookable.body:
CREATE OR REPLACE FUNCTION public.is_slot_bookable(_start_at timestamptz, _len integer)
RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  _cfg        public.booking_availability_config%ROWTYPE;
  _tz         text;
  _buffer     integer;
  _pitch      integer;
  _local      timestamp;
  _local_date date;
  _local_time time;
  _today      date;
  _r          record;
BEGIN
  SELECT * INTO _cfg FROM public.booking_availability_config WHERE id = 1;
  _tz     := COALESCE(_cfg.timezone, 'America/Toronto');
  _buffer := COALESCE(_cfg.buffer_minutes, 10);
  _pitch  := _len + _buffer;

  IF _start_at IS NULL OR _len IS NULL OR _len <= 0 THEN RETURN false; END IF;
  IF EXTRACT(SECOND FROM _start_at)::int <> 0 THEN RETURN false; END IF;
  IF _start_at < now() + make_interval(mins => COALESCE(_cfg.minimum_notice_minutes, 1440)) THEN
    RETURN false;
  END IF;

  _local      := _start_at AT TIME ZONE _tz;
  _local_date := _local::date;
  _local_time := _local::time;
  _today      := (now() AT TIME ZONE _tz)::date;

  -- Window in calendar dates, the same count the single-session page and
  -- Cal.com use: today + window_days is the last bookable date.
  IF _local_date > _today + COALESCE(_cfg.window_days, 8) THEN
    RETURN false;
  END IF;

  FOR _r IN SELECT * FROM public.booking_ranges_for_date(_local_date) LOOP
    IF _local_time >= _r.start_time
       AND _local_time + make_interval(mins => _len) <= _r.end_time
       AND mod(floor(extract(epoch FROM (_local_time - _r.start_time)) / 60)::integer, _pitch) = 0
    THEN
      RETURN true;
    END IF;
  END LOOP;
  RETURN false;
EXCEPTION WHEN OTHERS THEN
  RETURN false;
END;
$function$

redeem_booking_pass_v2.body:
CREATE OR REPLACE FUNCTION public.redeem_booking_pass_v2(
  _pass_id uuid, _idempotency_key text, _start_at timestamptz,
  _schedule_event_id uuid, _student_name text, _student_email text
)
RETURNS TABLE(redemption_id uuid, start_at timestamptz, end_at timestamptz, used_credits integer, total_credits integer, status text, was_existing boolean)
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  _pass public.booking_passes%ROWTYPE;
  _existing public.booking_pass_redemptions%ROWTYPE;
  _end_at timestamptz;
  _new_id uuid;
  _buffer integer := public.booking_buffer_minutes();
BEGIN
  SELECT * INTO _existing FROM public.booking_pass_redemptions
    WHERE booking_pass_id = _pass_id AND idempotency_key = _idempotency_key;
  IF FOUND THEN
    PERFORM pg_advisory_xact_lock(public.single_session_slot_lock_key(_existing.start_at));
    SELECT * INTO _pass FROM public.booking_passes WHERE id = _pass_id;
    redemption_id := _existing.id; start_at := _existing.start_at; end_at := _existing.end_at;
    used_credits := _pass.used_credits; total_credits := _pass.total_credits;
    status := _pass.status; was_existing := true; RETURN NEXT; RETURN;
  END IF;

  SELECT * INTO _pass FROM public.booking_passes WHERE id = _pass_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'pass_not_found'; END IF;
  SELECT * INTO _existing FROM public.booking_pass_redemptions
    WHERE booking_pass_id = _pass_id AND idempotency_key = _idempotency_key;
  IF FOUND THEN
    PERFORM pg_advisory_xact_lock(public.single_session_slot_lock_key(_existing.start_at));
    redemption_id := _existing.id; start_at := _existing.start_at; end_at := _existing.end_at;
    used_credits := _pass.used_credits; total_credits := _pass.total_credits;
    status := _pass.status; was_existing := true; RETURN NEXT; RETURN;
  END IF;
  IF _pass.status <> 'active' THEN RAISE EXCEPTION 'pass_not_active:%', _pass.status; END IF;
  IF _pass.expires_at IS NOT NULL AND _pass.expires_at < now() THEN
    UPDATE public.booking_passes SET status = 'expired' WHERE id = _pass_id;
    RAISE EXCEPTION 'pass_expired';
  END IF;
  IF _pass.used_credits >= _pass.total_credits THEN
    UPDATE public.booking_passes SET status = 'exhausted' WHERE id = _pass_id;
    RAISE EXCEPTION 'pass_exhausted';
  END IF;
  _end_at := _start_at + make_interval(mins => _pass.session_length_minutes);
  IF NOT public.is_slot_bookable(_start_at, _pass.session_length_minutes) THEN
    RAISE EXCEPTION 'slot_unavailable' USING ERRCODE = 'P0425';
  END IF;

  PERFORM pg_advisory_xact_lock(public.single_session_slot_lock_key(_start_at));
  IF NOT public.booking_slot_is_clear(_start_at, _end_at, _buffer, _buffer, NULL, NULL, _schedule_event_id) THEN
    RAISE EXCEPTION 'slot_conflict' USING ERRCODE = 'P0409';
  END IF;

  BEGIN
    INSERT INTO public.booking_pass_redemptions (
      booking_pass_id, schedule_event_id, google_event_id, start_at, end_at,
      status, idempotency_key, student_name_snapshot, student_email_snapshot,
      gcal_state, needs_gcal_sync
    ) VALUES (
      _pass_id, _schedule_event_id, NULL, _start_at, _end_at, 'booked',
      _idempotency_key, _student_name, _student_email, 'pending', true
    ) RETURNING id INTO _new_id;
  EXCEPTION WHEN unique_violation THEN
    SELECT * INTO _existing FROM public.booking_pass_redemptions
      WHERE booking_pass_id = _pass_id AND idempotency_key = _idempotency_key;
    redemption_id := _existing.id; start_at := _existing.start_at; end_at := _existing.end_at;
    used_credits := _pass.used_credits; total_credits := _pass.total_credits;
    status := _pass.status; was_existing := true; RETURN NEXT; RETURN;
  END;
  UPDATE public.booking_passes bp SET
    used_credits = bp.used_credits + 1,
    status = CASE WHEN bp.used_credits + 1 >= bp.total_credits THEN 'exhausted' ELSE 'active' END
  WHERE bp.id = _pass_id RETURNING * INTO _pass;
  redemption_id := _new_id; start_at := _start_at; end_at := _end_at;
  used_credits := _pass.used_credits; total_credits := _pass.total_credits;
  status := _pass.status; was_existing := false; RETURN NEXT;
END;
$function$

resolve_booking_link_full.body:
CREATE OR REPLACE FUNCTION public.resolve_booking_link_full(_slug text)
 RETURNS booking_passes
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _pass public.booking_passes%ROWTYPE;
BEGIN
  IF _slug IS NULL OR length(_slug) < 3 OR length(_slug) > 128 THEN RETURN NULL; END IF;
  -- 'exhausted' resolves so a spent pass renders its own page (0 remaining, no
  -- slots) instead of reading as an invalid link. Booking is still refused
  -- downstream: slots returns [] for any non-active status and book returns
  -- 409 no_sessions_remaining on zero credits. 'revoked' stays unresolvable.
  SELECT * INTO _pass FROM public.booking_passes
   WHERE booking_slug = _slug AND status IN ('active', 'paused', 'exhausted');
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF _pass.expires_at IS NOT NULL AND _pass.expires_at <= now() THEN
    UPDATE public.booking_passes SET status = 'expired' WHERE id = _pass.id;
    RETURN NULL;
  END IF;
  RETURN _pass;
END;
$function$

regenerate_booking_link.body:
CREATE OR REPLACE FUNCTION public.regenerate_booking_link(
  _student_id uuid, _new_slug text, _new_token_hash text
) RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _id uuid;
BEGIN
  IF NOT public.is_strong_booking_slug(_new_slug) THEN
    RAISE EXCEPTION 'invalid_booking_slug' USING ERRCODE = 'P0400';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(_student_id::text, 0));
  SELECT id INTO _id FROM public.booking_passes
   WHERE student_id = _student_id AND status IN ('active', 'paused')
   ORDER BY created_at DESC LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'no_resumable_pass'; END IF;
  UPDATE public.booking_passes
     SET booking_slug = _new_slug, token_hash = _new_token_hash
   WHERE id = _id;
  RETURN _new_slug;
END;
$$

generate_strong_booking_slug.body:
CREATE OR REPLACE FUNCTION public.generate_strong_booking_slug(_name text, _email text)
RETURNS text
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _alphabet constant text := 'abcdefghjkmnpqrstuvwxyz23456789';
  _base text;
  _email_base text;
  _bytes bytea;
  _code text := '';
  _i int;
BEGIN
  _base := lower(regexp_replace(COALESCE(split_part(trim(_name), ' ', 1), ''), '[^a-zA-Z0-9]', '', 'g'));
  _email_base := lower(regexp_replace(COALESCE(split_part(_email, '@', 1), ''), '[^a-zA-Z0-9]', '', 'g'));
  _base := left(COALESCE(NULLIF(_base, ''), NULLIF(_email_base, ''), 'student'), 20);
  _bytes := extensions.gen_random_bytes(26);
  FOR _i IN 0..25 LOOP
    _code := _code || substr(_alphabet, (get_byte(_bytes, _i) % length(_alphabet)) + 1, 1);
  END LOOP;
  RETURN _base || '-' || _code;
END;
$$

create_manual_booking_pass.body:
CREATE OR REPLACE FUNCTION public.create_manual_booking_pass(
  _student_name text,
  _student_email text,
  _total_credits int,
  _session_length_minutes int,
  _expires_at timestamptz,
  _notes text,
  _created_by uuid,
  _token_hash text,
  _booking_slug text
) RETURNS public.booking_passes
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _pass public.booking_passes%ROWTYPE;
BEGIN
  IF NULLIF(trim(_student_name), '') IS NULL AND NULLIF(trim(_student_email), '') IS NULL THEN
    RAISE EXCEPTION 'student_identity_required' USING ERRCODE = 'P0400';
  END IF;
  IF _total_credits IS NULL OR _total_credits NOT BETWEEN 1 AND 50 THEN
    RAISE EXCEPTION 'invalid_credits' USING ERRCODE = 'P0400';
  END IF;
  IF _session_length_minutes IS NULL OR _session_length_minutes NOT BETWEEN 15 AND 480 THEN
    RAISE EXCEPTION 'invalid_session_length' USING ERRCODE = 'P0400';
  END IF;
  IF _expires_at IS NOT NULL AND _expires_at <= now() THEN
    RAISE EXCEPTION 'invalid_expiry' USING ERRCODE = 'P0400';
  END IF;
  IF NOT public.is_strong_booking_slug(_booking_slug) THEN
    RAISE EXCEPTION 'invalid_booking_slug' USING ERRCODE = 'P0400';
  END IF;

  INSERT INTO public.booking_passes
    (token_hash, booking_slug, student_id, student_name, student_email,
     total_credits, session_length_minutes, expires_at, notes, created_by)
  VALUES
    (_token_hash, _booking_slug, NULL, NULLIF(trim(_student_name), ''), NULLIF(trim(_student_email), ''),
     _total_credits, _session_length_minutes, _expires_at, _notes, _created_by)
  RETURNING * INTO _pass;
  RETURN _pass;
END;
$$

regenerate_manual_booking_link.body:
CREATE OR REPLACE FUNCTION public.regenerate_manual_booking_link(
  _pass_id uuid, _new_slug text, _new_token_hash text
) RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT public.is_strong_booking_slug(_new_slug) THEN
    RAISE EXCEPTION 'invalid_booking_slug' USING ERRCODE = 'P0400';
  END IF;
  UPDATE public.booking_passes
     SET booking_slug = _new_slug, token_hash = _new_token_hash
   WHERE id = _pass_id AND student_id IS NULL AND status IN ('active', 'paused');
  IF NOT FOUND THEN RAISE EXCEPTION 'no_resumable_pass'; END IF;
  RETURN _new_slug;
END;
$$

rotate_weak_booking_slugs.body:
CREATE OR REPLACE FUNCTION public.rotate_weak_booking_slugs(_apply boolean DEFAULT false)
RETURNS TABLE (
  pass_id uuid,
  student_id uuid,
  student_name text,
  student_email text,
  old_slug text,
  new_slug text,
  applied boolean
)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _row public.booking_passes%ROWTYPE;
  _new_slug text;
BEGIN
  IF auth.role() <> 'service_role' AND NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = 'P0403';
  END IF;

  FOR _row IN
    SELECT * FROM public.booking_passes
     WHERE status IN ('active', 'paused') AND NOT public.is_strong_booking_slug(booking_slug)
     ORDER BY created_at, id
     FOR UPDATE
  LOOP
    LOOP
      _new_slug := public.generate_strong_booking_slug(_row.student_name, _row.student_email);
      EXIT WHEN NOT EXISTS (SELECT 1 FROM public.booking_passes bp WHERE bp.booking_slug = _new_slug);
    END LOOP;
    IF _apply THEN
      UPDATE public.booking_passes SET booking_slug = _new_slug WHERE id = _row.id;
    END IF;
    pass_id := _row.id;
    student_id := _row.student_id;
    student_name := _row.student_name;
    student_email := _row.student_email;
    old_slug := _row.booking_slug;
    new_slug := _new_slug;
    applied := _apply;
    RETURN NEXT;
  END LOOP;
END;
$$

enforce_booking_upload_limit.body:
CREATE OR REPLACE FUNCTION public.enforce_booking_upload_limit()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public
AS $$
DECLARE
  _count int;
BEGIN
  IF NEW.booking_pass_id IS NULL OR NEW.booking_idempotency_key IS NULL THEN
    RETURN NEW;
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.booking_pass_id::text || ':' || NEW.booking_idempotency_key, 0));
  SELECT count(*) INTO _count
  FROM public.external_work_uploads
  WHERE booking_pass_id = NEW.booking_pass_id
    AND booking_idempotency_key = NEW.booking_idempotency_key
    AND (TG_OP <> 'UPDATE' OR id <> NEW.id);
  IF _count >= 5 THEN
    RAISE EXCEPTION 'too_many_files' USING ERRCODE = 'P0400';
  END IF;
  RETURN NEW;
END;
$$

grant_booking_access.body:
CREATE OR REPLACE FUNCTION public.grant_booking_access(
  _student_id uuid,
  _student_name text,
  _student_email text,
  _total_credits int,
  _session_length_minutes int,
  _expires_at timestamptz,
  _created_by uuid,
  _token_hash text,
  _booking_slug text
) RETURNS public.booking_passes
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _pass public.booking_passes%ROWTYPE;
BEGIN
  IF _student_id IS NULL THEN RAISE EXCEPTION 'student_id_required' USING ERRCODE = 'P0400'; END IF;
  IF _total_credits IS NULL OR _total_credits NOT BETWEEN 1 AND 50 THEN
    RAISE EXCEPTION 'invalid_credits' USING ERRCODE = 'P0400';
  END IF;
  IF _session_length_minutes IS NULL OR _session_length_minutes NOT BETWEEN 15 AND 480 THEN
    RAISE EXCEPTION 'invalid_session_length' USING ERRCODE = 'P0400';
  END IF;
  IF _expires_at IS NOT NULL AND _expires_at <= now() THEN
    RAISE EXCEPTION 'invalid_expiry' USING ERRCODE = 'P0400';
  END IF;
  IF NOT public.is_strong_booking_slug(_booking_slug) THEN
    RAISE EXCEPTION 'invalid_booking_slug' USING ERRCODE = 'P0400';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(_student_id::text, 0));
  UPDATE public.booking_passes SET status = 'revoked'
   WHERE student_id = _student_id AND status IN ('active', 'paused');
  INSERT INTO public.booking_passes
    (token_hash, booking_slug, student_id, student_name, student_email,
     total_credits, session_length_minutes, expires_at, created_by)
  VALUES
    (_token_hash, _booking_slug, _student_id, _student_name, _student_email,
     _total_credits, _session_length_minutes, _expires_at, _created_by)
  RETURNING * INTO _pass;
  RETURN _pass;
END;
$$

mcp_require_admin.body:
create or replace function public.mcp_require_admin()
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  caller uuid := auth.uid();
begin
  if caller is null or not public.has_role(caller, 'admin') then
    raise exception 'admin authentication required';
  end if;
  return caller;
end;
$$

mcp_post_classroom_note.body:
create or replace function public.mcp_post_classroom_note(
  p_student_id uuid,
  p_title text,
  p_content_html text,
  p_idempotency_key text,
  p_description text default null,
  p_notify boolean default true
) returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  caller uuid := public.mcp_require_admin();
  prior jsonb;
  item_id uuid;
  conv_id uuid;
  route text;
  output jsonb;
begin
  if not exists (select 1 from public.profiles where class_id = p_student_id::text) then
    raise exception 'student not found';
  end if;
  if length(trim(coalesce(p_title, ''))) not between 1 and 160 then
    raise exception 'title must contain 1 to 160 characters';
  end if;
  if length(trim(coalesce(p_content_html, ''))) < 1
     or length(p_content_html) > 500000 then
    raise exception 'content_html must contain 1 to 500000 characters';
  end if;
  if length(trim(coalesce(p_idempotency_key, ''))) not between 8 and 160 then
    raise exception 'idempotency_key must contain 8 to 160 characters';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(caller::text || ':post_classroom_note:' || p_idempotency_key, 0)
  );
  select result into prior
  from public.mcp_write_audit
  where actor_id = caller
    and tool_name = 'post_classroom_note'
    and idempotency_key = p_idempotency_key;
  if prior is not null then
    return prior || jsonb_build_object('reused', true);
  end if;

  insert into public.classroom_items (
    student_id, class_id, created_by, type, title, description,
    content_html, status, visible_to_student, metadata_json
  )
  values (
    p_student_id, p_student_id, caller, 'note', trim(p_title),
    nullif(trim(coalesce(p_description, '')), ''), p_content_html,
    'assigned', true,
    jsonb_build_object(
      'mcp_tool', 'post_classroom_note',
      'mcp_idempotency_key', p_idempotency_key
    )
  )
  returning id into item_id;

  route := '/classroom/item/' || item_id::text;

  if p_notify then
    insert into public.notifications (user_id, type, title, body, link)
    values (
      p_student_id, 'assignment', 'New note: ' || trim(p_title),
      nullif(trim(coalesce(p_description, '')), ''), route
    );

    conv_id := public.mcp_get_or_create_admin_student_conversation(caller, p_student_id);
    insert into public.messages (conversation_id, sender_id, body)
    values (
      conv_id,
      caller,
      'New note: ' || trim(p_title) || E'\n\nView it in your Classroom: ' || route
    );
  end if;

  output := jsonb_build_object(
    'ok', true,
    'reused', false,
    'kind', 'note',
    'item_id', item_id,
    'student_id', p_student_id,
    'route', route,
    'notified', p_notify
  );
  insert into public.mcp_write_audit
    (actor_id, tool_name, idempotency_key, student_id, result)
  values
    (caller, 'post_classroom_note', p_idempotency_key, p_student_id, output);
  return output;
end;
$function$

