  p_response_schema jsonb,
  p_answer_key_html text,
  p_idempotency_key text,
  p_notify boolean default true
) returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  caller uuid := public.mcp_require_admin();
  prior jsonb;
  assignment_id uuid;
  conv_id uuid;
  route text;
  output jsonb;
begin
