  output := jsonb_build_object(
    'ok', true,
    'reused', false,
    'kind', 'passage_map_homework',
    'assignment_id', assignment_id,
    'student_id', p_student_id,
    'route', route,
    'answer_key', 'reveals_after_submission',
    'notified', p_notify
  );
  insert into public.mcp_write_audit
    (actor_id, tool_name, idempotency_key, student_id, result)
  values
    (caller, 'assign_passage_map_homework', p_idempotency_key, p_student_id, output);
  return output;
end;
$function$

mcp_assign_homework_set.body:
create or replace function public.mcp_assign_homework_set(
  p_set_id uuid,
  p_student_id uuid,
  p_idempotency_key text,
  p_notify boolean default true
) returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  caller uuid := public.mcp_require_admin();
  prior jsonb;
  hw record;
  assignment_id uuid;
  already_assigned boolean := false;
  conv_id uuid;
  route text;
  output jsonb;
begin
  if not exists (select 1 from public.profiles where class_id = p_student_id::text) then
    raise exception 'student not found';
  end if;
  if length(trim(coalesce(p_idempotency_key, ''))) not between 8 and 160 then
    raise exception 'idempotency_key must contain 8 to 160 characters';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(caller::text || ':assign_homework_set:' || p_idempotency_key, 0)
  );
  select result into prior
  from public.mcp_write_audit
  where actor_id = caller
    and tool_name = 'assign_homework_set'
    and idempotency_key = p_idempotency_key;
  if prior is not null then
    return prior || jsonb_build_object('reused', true);
  end if;

  select id, title, description, question_qids, class_id
    into hw
  from public.homework_sets
  where id = p_set_id;
  if hw.id is null then
    raise exception 'homework set not found';
  end if;

  begin
    insert into public.homework_assignments (
      set_id, student_id, question_qids, set_title, set_description,
      status, assigned_by, class_id
    )
    values (
      hw.id, p_student_id, hw.question_qids, hw.title, hw.description,
      'assigned', caller, hw.class_id
    )
    returning id into assignment_id;
  exception when unique_violation then
    already_assigned := true;
    select id into assignment_id
    from public.homework_assignments
    where set_id = hw.id and student_id = p_student_id
    limit 1;
  end;

  route := '/classroom/' || assignment_id::text;

  if not already_assigned then
    insert into public.classroom_items (
      student_id, created_by, type, title, description,
      source_table, source_id, status, visible_to_student, metadata_json
    )
    values (
      p_student_id, caller, 'homework', hw.title, hw.description,
      'homework_assignments', assignment_id, 'assigned', true,
      jsonb_build_object(
        'assigned_route', route,
        'mcp_tool', 'assign_homework_set',
        'mcp_idempotency_key', p_idempotency_key
      )
    );

    if p_notify then
      insert into public.notifications (user_id, type, title, body, link)
      values (
        p_student_id, 'assignment', 'New homework: ' || hw.title,
        nullif(trim(coalesce(hw.description, '')), ''), route
      );

      conv_id := public.mcp_get_or_create_admin_student_conversation(caller, p_student_id);
      insert into public.messages (conversation_id, sender_id, body)
      values (
        conv_id,
        caller,
        'New homework: ' || hw.title || E'\n\nStart it in your Classroom: ' || route
      );
    end if;
  end if;

  output := jsonb_build_object(
    'ok', true,
    'reused', false,
    'kind', 'homework_set',
    'assignment_id', assignment_id,
    'student_id', p_student_id,
    'set_id', hw.id,
    'title', hw.title,
    'route', route,
    'already_assigned', already_assigned,
    'notified', p_notify and not already_assigned
  );
  insert into public.mcp_write_audit
    (actor_id, tool_name, idempotency_key, student_id, result)
  values
    (caller, 'assign_homework_set', p_idempotency_key, p_student_id, output);
  return output;
end;
$function$

rename_pending_signup_notification.body:
CREATE OR REPLACE FUNCTION public.rename_pending_signup_notification()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF COALESCE(NEW.display_name, '') = '' THEN
    RETURN NEW;
  END IF;
  IF COALESCE(OLD.display_name, '') = COALESCE(NEW.display_name, '') THEN
    RETURN NEW;
  END IF;

  UPDATE public.notifications
  SET body = NEW.display_name || ' just signed up and is waiting for access.'
  WHERE type = 'signup'
    AND status = 'pending'
    AND subject_class_id = NEW.class_id;

  RETURN NEW;
END;
$$

apply_booking_package_payment.body:
CREATE OR REPLACE FUNCTION public.apply_booking_package_payment(
  _student_id uuid,
  _offer_id text,
  _provider_event_id text,
  _email text DEFAULT NULL
) RETURNS public.booking_passes
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  _offer public.booking_offers%ROWTYPE;
  _pass public.booking_passes%ROWTYPE;
BEGIN
  SELECT * INTO _offer FROM public.booking_offers WHERE id = _offer_id AND provider = 'stripe' AND active;
  IF NOT FOUND OR _offer.credits <= 0 THEN RAISE EXCEPTION 'not_a_package_offer'; END IF;

  IF EXISTS (SELECT 1 FROM public.booking_commerce_events WHERE provider = 'stripe' AND provider_event_id = _provider_event_id AND event_type = 'paid') THEN
    SELECT * INTO _pass FROM public.booking_passes WHERE student_id = _student_id ORDER BY created_at DESC LIMIT 1;
    RETURN _pass;
  END IF;

  SELECT * INTO _pass FROM public.booking_passes WHERE student_id = _student_id ORDER BY created_at DESC LIMIT 1 FOR UPDATE;
  IF FOUND THEN
    UPDATE public.booking_passes
      SET total_credits = total_credits + _offer.credits,
          status = 'active', expires_at = NULL
      WHERE id = _pass.id RETURNING * INTO _pass;
  ELSE
    INSERT INTO public.booking_passes (student_id, student_email, student_name, total_credits, used_credits, session_length_minutes, status)
      VALUES (_student_id, _email, COALESCE(_email, 'Student'), _offer.credits, 0, 70, 'active')
      RETURNING * INTO _pass;
  END IF;

  INSERT INTO public.booking_commerce_events (student_id, offer_id, provider, provider_event_id, event_type, email)
    VALUES (_student_id, _offer_id, 'stripe', _provider_event_id, 'paid', _email);
  RETURN _pass;
END;
$$

enforce_single_session_lifecycle.body:
CREATE OR REPLACE FUNCTION public.enforce_single_session_lifecycle()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public
AS $$
BEGIN
  NEW.updated_at := now();

  IF NEW.status = OLD.status THEN
    IF NEW.lifecycle_version <> OLD.lifecycle_version THEN
      RAISE EXCEPTION 'lifecycle_version_without_transition' USING ERRCODE = 'P0409';
    END IF;
    NEW.status_changed_at := OLD.status_changed_at;
    RETURN NEW;
  END IF;

  IF NEW.lifecycle_version <> OLD.lifecycle_version + 1 THEN
    RAISE EXCEPTION 'invalid_lifecycle_version' USING ERRCODE = 'P0409';
  END IF;

  IF NOT (
    (OLD.status = 'draft' AND NEW.status IN ('checkout_open', 'expired')) OR
    (
      OLD.status = 'draft'
      AND NEW.status = 'booked'
      AND NEW.amount_cents = 0
      AND EXISTS (
        SELECT 1
        FROM public.booking_event_types event_type
        WHERE event_type.slug = OLD.event_slug
          AND event_type.active
          AND event_type.requires_payment = false
          AND event_type.price_cents = 0
      )
    ) OR
    (OLD.status = 'checkout_open' AND NEW.status IN ('booked', 'expired', 'abandoned', 'refund_pending')) OR
    (OLD.status = 'expired' AND NEW.status IN ('booked', 'refund_pending')) OR
    (OLD.status = 'abandoned' AND NEW.status = 'refund_pending') OR
    (OLD.status = 'booked' AND NEW.status = 'cancelled') OR
    (OLD.status = 'refund_pending' AND NEW.status IN ('refunded', 'refund_failed')) OR
    (OLD.status = 'refund_failed' AND NEW.status = 'refunded')
  ) THEN
    RAISE EXCEPTION 'invalid_single_session_transition:%->%', OLD.status, NEW.status
      USING ERRCODE = 'P0409';
  END IF;

  NEW.status_changed_at := now();
  RETURN NEW;
END;
$$

set_single_session_tentative_event.body:
CREATE OR REPLACE FUNCTION public.set_single_session_tentative_event(
  _booking_id uuid,
  _expected_version integer,
  _gcal_event_id text
) RETURNS public.single_session_bookings
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE _booking public.single_session_bookings%ROWTYPE;
BEGIN
  UPDATE public.single_session_bookings b
    SET gcal_event_id = _gcal_event_id
  WHERE b.id = _booking_id AND b.status = 'draft'
    AND b.lifecycle_version = _expected_version
    AND (b.gcal_event_id IS NULL OR b.gcal_event_id = _gcal_event_id)
  RETURNING * INTO _booking;
  IF NOT FOUND THEN RAISE EXCEPTION 'stale_booking' USING ERRCODE = 'P0409'; END IF;
  RETURN _booking;
END;
$$

persist_single_session_checkout_fingerpr.body:
CREATE OR REPLACE FUNCTION public.persist_single_session_checkout_fingerprint(
  _booking_id uuid,
  _expected_version integer,
  _fingerprint_ciphertext text
) RETURNS public.single_session_bookings
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE _booking public.single_session_bookings%ROWTYPE;
BEGIN
  IF NULLIF(_fingerprint_ciphertext, '') IS NULL THEN
    RAISE EXCEPTION 'fingerprint_required' USING ERRCODE = 'P0400';
  END IF;
  UPDATE public.single_session_bookings b
    SET checkout_request_fingerprint = COALESCE(b.checkout_request_fingerprint, _fingerprint_ciphertext),
        checkout_fingerprint_disposition = 'persisted'
  WHERE b.id = _booking_id AND b.status = 'draft'
    AND b.lifecycle_version = _expected_version
    AND (b.checkout_request_fingerprint IS NULL OR b.checkout_request_fingerprint = _fingerprint_ciphertext)
  RETURNING * INTO _booking;
  IF NOT FOUND THEN RAISE EXCEPTION 'stale_booking' USING ERRCODE = 'P0409'; END IF;
  RETURN _booking;
END;
$$

attach_single_session_checkout.body:
CREATE OR REPLACE FUNCTION public.attach_single_session_checkout(
  _booking_id uuid,
  _expected_version integer,
  _stripe_checkout_session_id text,
  _stripe_checkout_url text,
  _stripe_expires_at timestamptz
) RETURNS public.single_session_bookings
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE _booking public.single_session_bookings%ROWTYPE;
BEGIN
  SELECT * INTO _booking FROM public.single_session_bookings WHERE id = _booking_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'booking_not_found' USING ERRCODE = 'P0404'; END IF;
  IF _booking.status = 'checkout_open' AND _booking.stripe_checkout_session_id = _stripe_checkout_session_id THEN
    RETURN _booking;
  END IF;
  IF _booking.status <> 'draft' OR _booking.lifecycle_version <> _expected_version
     OR _booking.checkout_request_fingerprint IS NULL THEN
    RAISE EXCEPTION 'stale_booking' USING ERRCODE = 'P0409';
  END IF;
  IF NULLIF(_stripe_checkout_session_id, '') IS NULL OR NULLIF(_stripe_checkout_url, '') IS NULL
     OR _stripe_expires_at <= now() THEN
    RAISE EXCEPTION 'invalid_checkout' USING ERRCODE = 'P0400';
  END IF;

  UPDATE public.single_session_bookings b SET
    status = 'checkout_open', lifecycle_version = b.lifecycle_version + 1,
    stripe_checkout_session_id = _stripe_checkout_session_id,
    stripe_checkout_url = _stripe_checkout_url,
    stripe_expires_at = _stripe_expires_at,
    checkout_request_fingerprint = NULL,
    checkout_fingerprint_disposition = 'attached'
  WHERE b.id = _booking_id
  RETURNING * INTO _booking;
  RETURN _booking;
END;
$$

expire_single_session_draft.body:
CREATE OR REPLACE FUNCTION public.expire_single_session_draft(
  _booking_id uuid,
  _expected_version integer,
  _reason text
) RETURNS public.single_session_bookings
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE _booking public.single_session_bookings%ROWTYPE;
BEGIN
  UPDATE public.single_session_bookings b SET
    status = 'expired', lifecycle_version = b.lifecycle_version + 1,
    terminal_reason = COALESCE(NULLIF(_reason, ''), 'draft_failed')
  WHERE b.id = _booking_id AND b.status = 'draft' AND b.lifecycle_version = _expected_version
  RETURNING * INTO _booking;
  IF NOT FOUND THEN
    SELECT * INTO _booking FROM public.single_session_bookings WHERE id = _booking_id;
    IF _booking.status = 'expired' THEN RETURN _booking; END IF;
    RAISE EXCEPTION 'stale_booking' USING ERRCODE = 'P0409';
  END IF;
  IF _booking.gcal_event_id IS NOT NULL THEN
    PERFORM public.enqueue_single_session_outbox(_booking.id, 'gcal_delete', 'system', 'pending',
      _booking.status, _booking.lifecycle_version, NULL);
  END IF;
  RETURN _booking;
END;
$$

expire_single_session_checkout.body:
CREATE OR REPLACE FUNCTION public.expire_single_session_checkout(
  _booking_id uuid,
  _stripe_checkout_session_id text,
  _reason text
) RETURNS public.single_session_bookings
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE _booking public.single_session_bookings%ROWTYPE;
BEGIN
  SELECT * INTO _booking FROM public.single_session_bookings WHERE id = _booking_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'booking_not_found' USING ERRCODE = 'P0404'; END IF;
  IF _booking.status = 'expired' THEN RETURN _booking; END IF;
  IF _booking.status <> 'checkout_open'
     OR _booking.stripe_checkout_session_id IS DISTINCT FROM _stripe_checkout_session_id THEN
    RAISE EXCEPTION 'stale_booking' USING ERRCODE = 'P0409';
  END IF;
  UPDATE public.single_session_bookings b SET
    status = 'expired', lifecycle_version = b.lifecycle_version + 1,
    terminal_reason = COALESCE(NULLIF(_reason, ''), 'checkout_expired')
  WHERE b.id = _booking_id RETURNING * INTO _booking;
  IF _booking.gcal_event_id IS NOT NULL THEN
    PERFORM public.enqueue_single_session_outbox(_booking.id, 'gcal_delete', 'system', 'pending',
      _booking.status, _booking.lifecycle_version, NULL);
  END IF;
  RETURN _booking;
END;
$$

abandon_single_session_booking.body:
CREATE OR REPLACE FUNCTION public.abandon_single_session_booking(
  _booking_id uuid,
  _booking_token_hash text
) RETURNS public.single_session_bookings
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE _booking public.single_session_bookings%ROWTYPE;
BEGIN
  SELECT * INTO _booking FROM public.single_session_bookings WHERE id = _booking_id FOR UPDATE;
  IF NOT FOUND OR _booking.booking_token_hash IS DISTINCT FROM _booking_token_hash
     OR _booking.booking_token_expires_at <= now() THEN
    RAISE EXCEPTION 'invalid_booking_token' USING ERRCODE = 'P0403';
  END IF;
  IF _booking.status = 'abandoned' THEN RETURN _booking; END IF;
  IF _booking.status <> 'checkout_open' THEN
    RAISE EXCEPTION 'abandon_not_allowed' USING ERRCODE = 'P0409';
  END IF;
  UPDATE public.single_session_bookings b SET
    status = 'abandoned', lifecycle_version = b.lifecycle_version + 1,
    terminal_reason = 'booker_abandoned'
  WHERE b.id = _booking_id RETURNING * INTO _booking;
  IF _booking.gcal_event_id IS NOT NULL THEN
    PERFORM public.enqueue_single_session_outbox(_booking.id, 'gcal_delete', 'system', 'pending',
      _booking.status, _booking.lifecycle_version, NULL);
  END IF;
  RETURN _booking;
END;
$$

finalize_single_session_payment.body:
CREATE OR REPLACE FUNCTION public.finalize_single_session_payment(
  _booking_id uuid,
  _provider_event_id text,
  _stripe_checkout_session_id text,
  _stripe_payment_intent_id text,
  _amount_cents integer,
  _currency text,
  _livemode boolean,
  _live_calendar_clear boolean,
  _cancel_token_hash text,
  _cancel_payload_ciphertext text
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _booking public.single_session_bookings%ROWTYPE;
  _event public.booking_event_types%ROWTYPE;
  _claimed_booking_id uuid;
  _can_book boolean := false;
  _new_version integer;
  _slot_start timestamptz;
  _expected_amount integer;
  _expected_currency text;
BEGIN
  IF NULLIF(_provider_event_id, '') IS NULL
     OR NULLIF(_stripe_checkout_session_id, '') IS NULL
     OR NULLIF(_stripe_payment_intent_id, '') IS NULL
     OR _amount_cents IS NULL OR _amount_cents < 0
     OR NULLIF(lower(COALESCE(_currency, '')), '') IS NULL
     OR _livemode IS NULL THEN
    RAISE EXCEPTION 'invalid_payment_facts' USING ERRCODE = 'P0400';
  END IF;

  SELECT start_at INTO _slot_start FROM public.single_session_bookings WHERE id = _booking_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'booking_not_found' USING ERRCODE = 'P0404'; END IF;
  PERFORM pg_advisory_xact_lock(public.single_session_slot_lock_key(_slot_start));
  SELECT * INTO _booking FROM public.single_session_bookings WHERE id = _booking_id FOR UPDATE;
  SELECT * INTO _event FROM public.booking_event_types WHERE slug = _booking.event_slug;
  IF NOT FOUND OR _event.requires_payment IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'payment_not_required' USING ERRCODE = 'P0400';
  END IF;

  _expected_amount := COALESCE(
    _booking.quoted_amount_cents,
    public.booking_price_cents(_booking.event_slug, _booking.email)
  );
  _expected_currency := lower(COALESCE(_booking.quoted_currency, _event.currency));
  IF _amount_cents IS DISTINCT FROM _expected_amount
     OR lower(_currency) IS DISTINCT FROM _expected_currency THEN
    RAISE EXCEPTION 'invalid_payment_facts' USING ERRCODE = 'P0400';
  END IF;

  SELECT single_session_booking_id INTO _claimed_booking_id
  FROM public.booking_commerce_events
  WHERE provider = 'stripe' AND provider_event_id = _provider_event_id
    AND event_type = 'single_session_paid';
  IF FOUND AND _claimed_booking_id IS DISTINCT FROM _booking_id THEN
    RAISE EXCEPTION 'provider_event_already_claimed' USING ERRCODE = 'P0409';
  END IF;

  IF _booking.stripe_checkout_session_id IS DISTINCT FROM _stripe_checkout_session_id THEN
    RAISE EXCEPTION 'checkout_mismatch' USING ERRCODE = 'P0409';
  END IF;

  IF _booking.status IN ('booked', 'cancelled', 'refund_pending', 'refunded', 'refund_failed') THEN
    IF _booking.stripe_payment_intent_id IS DISTINCT FROM _stripe_payment_intent_id
       OR _booking.amount_cents IS DISTINCT FROM _amount_cents
       OR lower(_booking.currency) IS DISTINCT FROM lower(_currency)
       OR _booking.livemode IS DISTINCT FROM _livemode THEN
      RAISE EXCEPTION 'payment_facts_mismatch' USING ERRCODE = 'P0409';
    END IF;
    INSERT INTO public.booking_commerce_events (
      provider, provider_event_id, event_type, offer_id, amount_cents, currency,
      payload, single_session_booking_id
    ) VALUES (
      'stripe', _provider_event_id, 'single_session_paid', NULL,
      _amount_cents, lower(_currency),
      jsonb_build_object('livemode', _livemode, 'checkout_session_id', _stripe_checkout_session_id),
      _booking_id
    ) ON CONFLICT (provider, provider_event_id, event_type) DO NOTHING;
    RETURN jsonb_build_object('booking_id', _booking.id, 'status', _booking.status,
      'lifecycle_version', _booking.lifecycle_version, 'was_existing', true);
  END IF;

  IF _booking.status NOT IN ('checkout_open', 'expired', 'abandoned') THEN
    RAISE EXCEPTION 'payment_not_finalizable' USING ERRCODE = 'P0409';
  END IF;

  INSERT INTO public.booking_commerce_events (
    provider, provider_event_id, event_type, offer_id, amount_cents, currency,
    payload, single_session_booking_id
  ) VALUES (
    'stripe', _provider_event_id, 'single_session_paid', NULL,
    _amount_cents, lower(_currency),
    jsonb_build_object('livemode', _livemode, 'checkout_session_id', _stripe_checkout_session_id),
    _booking_id
  ) ON CONFLICT (provider, provider_event_id, event_type) DO NOTHING;

  _can_book := _live_calendar_clear
    AND (_booking.status = 'checkout_open'
      OR (_booking.status = 'expired' AND _booking.status_changed_at >= now() - interval '10 minutes'))
    AND public.booking_slot_is_clear(
      _booking.start_at, _booking.end_at,
      COALESCE(_event.buffer_before_minutes, 0), COALESCE(_event.buffer_after_minutes, 0),
      _booking.id, _booking.gcal_event_id, NULL
    );

  IF _can_book THEN
    IF NULLIF(_cancel_token_hash, '') IS NULL OR NULLIF(_cancel_payload_ciphertext, '') IS NULL THEN
      RAISE EXCEPTION 'cancel_capability_required' USING ERRCODE = 'P0400';
    END IF;
    UPDATE public.single_session_bookings b SET
      status = 'booked', lifecycle_version = b.lifecycle_version + 1,
      stripe_payment_intent_id = _stripe_payment_intent_id,
      amount_cents = _amount_cents, currency = lower(_currency), livemode = _livemode,
      cancel_token_hash = _cancel_token_hash, cancel_token_expires_at = b.start_at,
      terminal_reason = NULL
    WHERE b.id = _booking_id RETURNING * INTO _booking;
    _new_version := _booking.lifecycle_version;

    PERFORM public.enqueue_single_session_outbox(_booking.id, 'gcal_promote', 'system', 'pending',
      'booked', _new_version, NULL);
    PERFORM public.enqueue_single_session_outbox(_booking.id, 'email_booking_confirmation', 'booker', 'blocked',
      'booked', _new_version, _cancel_payload_ciphertext);
    PERFORM public.enqueue_single_session_outbox(_booking.id, 'email_admin_notification', 'admin', 'blocked',
      'booked', _new_version, NULL);
  ELSE
    UPDATE public.single_session_bookings b SET
      status = 'refund_pending', lifecycle_version = b.lifecycle_version + 1,
      stripe_payment_intent_id = _stripe_payment_intent_id,
      amount_cents = _amount_cents, currency = lower(_currency), livemode = _livemode,
      terminal_reason = 'paid_slot_unavailable'
    WHERE b.id = _booking_id RETURNING * INTO _booking;
    _new_version := _booking.lifecycle_version;
    UPDATE public.single_session_outbox SET state = 'superseded', updated_at = now()
      WHERE booking_id = _booking.id AND state IN ('blocked', 'pending', 'failed')
        AND action IN ('gcal_promote', 'email_booking_confirmation', 'email_admin_notification');
    PERFORM public.enqueue_single_session_outbox(_booking.id, 'gcal_delete', 'system', 'pending',
      'refund_pending', _new_version, NULL);
    PERFORM public.enqueue_single_session_outbox(_booking.id, 'stripe_refund', 'system', 'pending',
      'refund_pending', _new_version, NULL);
  END IF;

  RETURN jsonb_build_object('booking_id', _booking.id, 'status', _booking.status,
    'lifecycle_version', _booking.lifecycle_version, 'was_existing', false);
END;
$$

cancel_single_session_booking.body:
CREATE OR REPLACE FUNCTION public.cancel_single_session_booking(_cancel_token_hash text)
RETURNS public.single_session_bookings
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE _booking public.single_session_bookings%ROWTYPE;
BEGIN
  SELECT * INTO _booking FROM public.single_session_bookings
  WHERE cancel_token_hash = _cancel_token_hash FOR UPDATE;
  IF NOT FOUND OR _booking.cancel_token_expires_at <= now() THEN
    RAISE EXCEPTION 'invalid_cancel_token' USING ERRCODE = 'P0403';
  END IF;
  IF _booking.status = 'cancelled' THEN RETURN _booking; END IF;
  IF _booking.status <> 'booked' THEN
    RAISE EXCEPTION 'cancel_not_allowed' USING ERRCODE = 'P0409';
  END IF;
  UPDATE public.single_session_bookings b SET
    status = 'cancelled', lifecycle_version = b.lifecycle_version + 1,
    terminal_reason = 'booker_cancelled'
  WHERE b.id = _booking.id RETURNING * INTO _booking;

  UPDATE public.single_session_outbox SET state = 'superseded', updated_at = now()
  WHERE booking_id = _booking.id AND state IN ('blocked', 'pending', 'failed')
    AND action IN ('gcal_promote', 'email_booking_confirmation', 'email_admin_notification');
  PERFORM public.enqueue_single_session_outbox(_booking.id, 'gcal_delete', 'system', 'pending',
    'cancelled', _booking.lifecycle_version, NULL);
  PERFORM public.enqueue_single_session_outbox(_booking.id, 'email_cancellation', 'booker', 'pending',
    'cancelled', _booking.lifecycle_version, NULL);
  PERFORM public.enqueue_single_session_outbox(_booking.id, 'email_cancellation', 'admin', 'pending',
    'cancelled', _booking.lifecycle_version, NULL);
  RETURN _booking;
END;
$$

complete_single_session_outbox.body:
CREATE OR REPLACE FUNCTION public.complete_single_session_outbox(
  _job_id uuid,
  _lease_token uuid,
  _provider_status text DEFAULT NULL,
  _result jsonb DEFAULT '{}'::jsonb,
  _meet_url text DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  _job public.single_session_outbox%ROWTYPE;
  _booking public.single_session_bookings%ROWTYPE;
  _compensate boolean := false;
  _refund_id text;
BEGIN
  SELECT * INTO _job FROM public.single_session_outbox WHERE id = _job_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'outbox_job_not_found' USING ERRCODE = 'P0404'; END IF;
  IF _job.state <> 'leased' OR _job.lease_token IS DISTINCT FROM _lease_token
     OR _job.lease_until <= now() THEN
    RAISE EXCEPTION 'outbox_lease_lost' USING ERRCODE = 'P0409';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('single-session-side-effect:' || _job.booking_id::text, 0));
  SELECT * INTO _booking FROM public.single_session_bookings WHERE id = _job.booking_id FOR UPDATE;
  IF _booking.status <> _job.precondition_status
     OR _booking.lifecycle_version <> _job.precondition_lifecycle_version THEN
    _compensate := _job.action = 'gcal_promote';
    UPDATE public.single_session_outbox SET
      state = 'superseded', lease_worker_id = NULL, lease_token = NULL,
      lease_until = NULL, last_error = 'lifecycle changed during side effect', updated_at = now()
    WHERE id = _job_id;
    RETURN jsonb_build_object('applied', false, 'compensate', _compensate);
  END IF;

  IF _job.action = 'gcal_promote' THEN
    IF NULLIF(_meet_url, '') IS NULL THEN
      RAISE EXCEPTION 'meet_url_required' USING ERRCODE = 'P0400';
    END IF;
    UPDATE public.single_session_bookings SET meet_url = _meet_url WHERE id = _booking.id;
    UPDATE public.single_session_outbox SET state = 'pending', next_retry_at = now(), updated_at = now()
    WHERE booking_id = _booking.id AND state = 'blocked'
      AND action IN ('email_booking_confirmation', 'email_admin_notification')
      AND precondition_status = _booking.status
      AND precondition_lifecycle_version = _booking.lifecycle_version;
  ELSIF _job.action = 'stripe_refund' THEN
    _refund_id := NULLIF(_result->>'refund_id', '');
    IF _refund_id IS NOT NULL THEN
      UPDATE public.single_session_bookings SET
        stripe_refund_id = COALESCE(stripe_refund_id, _refund_id),
        stripe_refund_status = COALESCE(_provider_status, stripe_refund_status)
      WHERE id = _booking.id;
    END IF;
    IF lower(COALESCE(_provider_status, '')) = 'succeeded' THEN
      UPDATE public.single_session_bookings b SET
        status = 'refunded', lifecycle_version = b.lifecycle_version + 1,
        stripe_refund_status = 'succeeded'
      WHERE b.id = _booking.id RETURNING * INTO _booking;
      PERFORM public.enqueue_single_session_outbox(_booking.id, 'email_refund_apology', 'booker', 'pending',
        'refunded', _booking.lifecycle_version, NULL);
    END IF;
  END IF;

  UPDATE public.single_session_outbox SET
    state = 'succeeded', provider_status = _provider_status,
    result = COALESCE(_result, '{}'::jsonb), payload_ciphertext = NULL,
    sensitive_payload_purged_at = CASE WHEN payload_ciphertext IS NULL
      THEN sensitive_payload_purged_at ELSE now() END,
    lease_worker_id = NULL, lease_token = NULL, lease_until = NULL,
    completed_at = now(), updated_at = now()
  WHERE id = _job_id;
  RETURN jsonb_build_object('applied', true, 'compensate', false);
END;
$$

fail_single_session_outbox.body:
CREATE OR REPLACE FUNCTION public.fail_single_session_outbox(
  _job_id uuid,
  _lease_token uuid,
  _error text,
  _provider_status text DEFAULT NULL,
  _confirmed_failure boolean DEFAULT false
) RETURNS public.single_session_outbox
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  _job public.single_session_outbox%ROWTYPE;
  _booking public.single_session_bookings%ROWTYPE;
  _terminal boolean;
BEGIN
  SELECT * INTO _job FROM public.single_session_outbox WHERE id = _job_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'outbox_job_not_found' USING ERRCODE = 'P0404'; END IF;
  IF _job.state <> 'leased' OR _job.lease_token IS DISTINCT FROM _lease_token THEN
    RAISE EXCEPTION 'outbox_lease_lost' USING ERRCODE = 'P0409';
  END IF;
  SELECT * INTO _booking FROM public.single_session_bookings WHERE id = _job.booking_id FOR UPDATE;

  IF _booking.status <> _job.precondition_status
     OR _booking.lifecycle_version <> _job.precondition_lifecycle_version THEN
    UPDATE public.single_session_outbox SET
      state = 'superseded', lease_worker_id = NULL, lease_token = NULL,
      lease_until = NULL, last_error = 'lifecycle changed during side effect', updated_at = now()
    WHERE id = _job_id RETURNING * INTO _job;
    RETURN _job;
  END IF;

  _terminal := _confirmed_failure OR _job.attempts >= _job.max_attempts;
  IF _job.action = 'stripe_refund' AND _confirmed_failure THEN
    UPDATE public.single_session_bookings b SET
      status = 'refund_failed', lifecycle_version = b.lifecycle_version + 1,
      stripe_refund_status = COALESCE(NULLIF(_provider_status, ''), 'failed')
    WHERE b.id = _booking.id AND b.status = 'refund_pending';
  ELSIF _job.action = 'stripe_refund' AND _terminal THEN
    -- Retries ended without a definitive provider answer. Money stays pending;
    -- persist an operator-visible alert instead of declaring a false failure.
    INSERT INTO public.booking_calendar_alerts (
      redemption_id, single_session_booking_id, alert_type, status, details
    ) VALUES (
      NULL, _booking.id, 'refund_attention', 'open',
      jsonb_build_object('outbox_job_id', _job.id, 'attempts', _job.attempts,
        'last_error', left(COALESCE(_error, 'unknown outcome'), 1000))
    )
    ON CONFLICT (single_session_booking_id, alert_type)
      WHERE status = 'open' AND single_session_booking_id IS NOT NULL
    DO UPDATE SET details = excluded.details;
  END IF;

  UPDATE public.single_session_outbox SET
    state = CASE WHEN _terminal THEN 'failed' ELSE 'pending' END,
    provider_status = _provider_status, last_error = left(COALESCE(_error, 'unknown failure'), 4000),
    lease_worker_id = NULL, lease_token = NULL, lease_until = NULL,
    next_retry_at = CASE WHEN _terminal THEN next_retry_at ELSE
      now() + least(interval '1 hour', make_interval(secs => (15 * power(2, greatest(attempts - 1, 0)))::integer)) END,
    updated_at = now()
  WHERE id = _job_id RETURNING * INTO _job;

  IF _job.action = 'gcal_promote' AND _terminal THEN
    UPDATE public.single_session_outbox SET
      state = 'pending', next_retry_at = now(), provider_status = 'meet_link_pending', updated_at = now()
    WHERE booking_id = _booking.id AND state = 'blocked'
      AND action IN ('email_booking_confirmation', 'email_admin_notification')
      AND precondition_status = _booking.status
      AND precondition_lifecycle_version = _booking.lifecycle_version;
  END IF;
  RETURN _job;
END;
$$

record_single_session_refund_status.body:
CREATE OR REPLACE FUNCTION public.record_single_session_refund_status(
  _booking_id uuid,
  _stripe_refund_id text,
  _provider_status text
) RETURNS public.single_session_bookings
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE _booking public.single_session_bookings%ROWTYPE;
BEGIN
  SELECT * INTO _booking FROM public.single_session_bookings WHERE id = _booking_id FOR UPDATE;
  IF NOT FOUND OR _booking.status NOT IN ('refund_pending', 'refund_failed', 'refunded') THEN
    RAISE EXCEPTION 'not_in_refund_branch' USING ERRCODE = 'P0409';
  END IF;
  IF _booking.stripe_refund_id IS NOT NULL
     AND _booking.stripe_refund_id IS DISTINCT FROM _stripe_refund_id THEN
    RAISE EXCEPTION 'refund_id_mismatch' USING ERRCODE = 'P0409';
  END IF;
  IF lower(_provider_status) = 'succeeded' AND _booking.status <> 'refunded' THEN
    UPDATE public.single_session_bookings b SET
      status = 'refunded', lifecycle_version = b.lifecycle_version + 1,
      stripe_refund_id = _stripe_refund_id, stripe_refund_status = 'succeeded'
    WHERE b.id = _booking_id RETURNING * INTO _booking;
    PERFORM public.enqueue_single_session_outbox(_booking.id, 'email_refund_apology', 'booker', 'pending',
      'refunded', _booking.lifecycle_version, NULL);
  ELSIF lower(_provider_status) IN ('failed', 'canceled') AND _booking.status = 'refund_pending' THEN
    UPDATE public.single_session_bookings b SET
      status = 'refund_failed', lifecycle_version = b.lifecycle_version + 1,
      stripe_refund_id = _stripe_refund_id, stripe_refund_status = lower(_provider_status)
    WHERE b.id = _booking_id RETURNING * INTO _booking;
  ELSE
    UPDATE public.single_session_bookings SET
      stripe_refund_id = COALESCE(stripe_refund_id, _stripe_refund_id),
      stripe_refund_status = lower(_provider_status)
    WHERE id = _booking_id RETURNING * INTO _booking;
  END IF;
  RETURN _booking;
END;
$$

resolve_single_session_sweep.body:
CREATE OR REPLACE FUNCTION public.resolve_single_session_sweep(
  _booking_id uuid,
  _sweep_lease_token uuid,
  _resolution text,
  _stripe_session_id text DEFAULT NULL,
  _stripe_expires_at timestamptz DEFAULT NULL
) RETURNS public.single_session_bookings
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE _booking public.single_session_bookings%ROWTYPE;
BEGIN
  SELECT * INTO _booking FROM public.single_session_bookings WHERE id = _booking_id FOR UPDATE;
  IF NOT FOUND OR _booking.sweep_lease_token IS DISTINCT FROM _sweep_lease_token
     OR _booking.sweep_lease_until <= now() THEN
    RAISE EXCEPTION 'sweep_lease_lost' USING ERRCODE = 'P0409';
  END IF;
  IF _resolution NOT IN ('expired_no_checkout', 'stripe_expired', 'stripe_absent') THEN
    RAISE EXCEPTION 'invalid_sweep_resolution' USING ERRCODE = 'P0400';
  END IF;
  IF _stripe_session_id IS NOT NULL AND _stripe_expires_at IS NULL THEN
    RAISE EXCEPTION 'stripe_expiry_required' USING ERRCODE = 'P0400';
  END IF;

  UPDATE public.single_session_bookings b SET
    stripe_checkout_session_id = COALESCE(b.stripe_checkout_session_id, _stripe_session_id),
    stripe_expires_at = COALESCE(b.stripe_expires_at, _stripe_expires_at),
    checkout_request_fingerprint = CASE WHEN _resolution IN ('stripe_expired', 'stripe_absent')
      THEN NULL ELSE b.checkout_request_fingerprint END,
    checkout_fingerprint_disposition = CASE _resolution
      WHEN 'stripe_expired' THEN 'stripe_expired'
      WHEN 'stripe_absent' THEN 'stripe_absent'
      ELSE b.checkout_fingerprint_disposition END,
    status = CASE WHEN b.status IN ('draft', 'checkout_open') THEN 'expired' ELSE b.status END,
    lifecycle_version = CASE WHEN b.status IN ('draft', 'checkout_open')
      THEN b.lifecycle_version + 1 ELSE b.lifecycle_version END,
    terminal_reason = CASE WHEN b.status IN ('draft', 'checkout_open') THEN _resolution ELSE b.terminal_reason END,
    sweep_worker_id = NULL, sweep_lease_token = NULL, sweep_lease_until = NULL
  WHERE b.id = _booking_id RETURNING * INTO _booking;
  IF _booking.gcal_event_id IS NOT NULL THEN
    PERFORM public.enqueue_single_session_outbox(_booking.id, 'gcal_delete', 'system', 'pending',
      _booking.status, _booking.lifecycle_version, NULL);
  END IF;
  RETURN _booking;
END;
$$

