single_session_booking_window_end.body:
CREATE OR REPLACE FUNCTION public.single_session_booking_window_end(_now timestamptz DEFAULT now(), _event_slug text DEFAULT 'single-session'::text)
RETURNS date
LANGUAGE plpgsql STABLE
SET search_path TO 'public'
AS $function$
DECLARE
  _tz text := COALESCE(
    (SELECT timezone FROM public.booking_availability_config WHERE id = 1),
    'America/Toronto'
  );
  _day date := (_now AT TIME ZONE _tz)::date;
  _event public.booking_event_types%ROWTYPE;
  _target integer;
  _business_days integer := 0;
BEGIN
  SELECT * INTO _event FROM public.booking_event_types WHERE slug = _event_slug;
  IF FOUND AND _event.window_calendar_days IS NOT NULL THEN
    RETURN _day + _event.window_calendar_days;
  END IF;
  _target := COALESCE(_event.window_business_days, 6);
  WHILE _business_days < _target LOOP
    IF extract(isodow FROM _day) BETWEEN 1 AND 5 THEN
      _business_days := _business_days + 1;
    END IF;
    IF _business_days < _target THEN _day := _day + 1; END IF;
  END LOOP;
  RETURN _day;
END;
$function$

is_single_session_slot_bookable.body:
CREATE OR REPLACE FUNCTION public.is_single_session_slot_bookable(_start_at timestamptz, _now timestamptz DEFAULT now(), _event_slug text DEFAULT 'single-session'::text)
RETURNS boolean
LANGUAGE plpgsql STABLE
SET search_path TO 'public'
AS $function$
DECLARE
  _tz text := COALESCE(
    (SELECT timezone FROM public.booking_availability_config WHERE id = 1),
    'America/Toronto'
  );
  _event public.booking_event_types%ROWTYPE;
  _length integer;
  _pitch integer;
  _local_start timestamp;
  _local_date date;
  _local_time time;
BEGIN
  SELECT * INTO _event FROM public.booking_event_types WHERE slug = _event_slug AND active;
  IF NOT FOUND THEN RETURN false; END IF;
  IF _start_at IS NULL THEN RETURN false; END IF;

  IF _event.pinned_start_at IS NOT NULL THEN
    RETURN _start_at = _event.pinned_start_at AND _start_at > _now;
  END IF;

  _length := _event.length_minutes;
  _pitch := COALESCE(_event.slot_interval_minutes, _event.length_minutes);

  IF _start_at < _now + make_interval(mins => _event.minimum_notice_minutes) THEN
    RETURN false;
  END IF;

  _local_start := _start_at AT TIME ZONE _tz;
  _local_date := _local_start::date;
  _local_time := _local_start::time;

  IF _local_date < (_now AT TIME ZONE _tz)::date
     OR _local_date > public.single_session_booking_window_end(_now, _event_slug) THEN
    RETURN false;
  END IF;

  RETURN EXISTS (
    SELECT 1
    FROM public.booking_ranges_for_date(_local_date) a
    WHERE _local_time >= a.start_time
      AND _local_time + make_interval(mins => _length) <= a.end_time
      AND mod(
        floor(extract(epoch FROM (_local_time - a.start_time)) / 60)::integer,
        _pitch
      ) = 0
  );
EXCEPTION WHEN OTHERS THEN
  RETURN false;
END;
$function$

claim_single_session_slot.body:
CREATE OR REPLACE FUNCTION public.claim_single_session_slot(
  _start_at timestamptz,
  _name text,
  _email text,
  _notes text,
  _guests jsonb,
  _client_idempotency_key text,
  _booking_token_hash text,
  _ip_hash text,
  _user_id uuid DEFAULT NULL,
  _event_slug text DEFAULT 'single-session',
  _booker_timezone text DEFAULT 'America/Toronto'
) RETURNS public.single_session_bookings
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _booking public.single_session_bookings%ROWTYPE;
  _timezone text := NULLIF(trim(_booker_timezone), '');
  _amount integer;
  _currency text;
BEGIN
  IF _timezone IS NULL OR NOT EXISTS (
    SELECT 1 FROM pg_catalog.pg_timezone_names WHERE name = _timezone
  ) THEN
    RAISE EXCEPTION 'invalid_timezone' USING ERRCODE = 'P0400';
  END IF;

  _booking := public.claim_single_session_slot_without_confirmation_details(
    _start_at, _name, _email, _notes, _guests, _client_idempotency_key,
    _booking_token_hash, _ip_hash, _user_id, _event_slug
  );

  _amount := public.booking_price_cents(_booking.event_slug, _booking.email);
  SELECT lower(currency) INTO _currency
  FROM public.booking_event_types WHERE slug = _booking.event_slug;
  IF _amount IS NULL OR _currency IS NULL THEN
    RAISE EXCEPTION 'invalid_event_price' USING ERRCODE = 'P0400';
  END IF;

  UPDATE public.single_session_bookings b
  SET booker_timezone = COALESCE(b.booker_timezone, _timezone),
      quoted_amount_cents = COALESCE(b.quoted_amount_cents, _amount),
      quoted_currency = COALESCE(b.quoted_currency, _currency)
  WHERE b.id = _booking.id
  RETURNING * INTO _booking;

  RETURN _booking;
END;
$$

finalize_single_session_free.body:
CREATE OR REPLACE FUNCTION public.finalize_single_session_free(_booking_id uuid, _expected_version integer, _live_calendar_clear boolean, _cancel_token_hash text, _cancel_payload_ciphertext text)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  _booking public.single_session_bookings%ROWTYPE;
  _event public.booking_event_types%ROWTYPE;
  _can_book boolean := false;
  _new_version integer;
  _slot_start timestamptz;
BEGIN
  SELECT start_at INTO _slot_start FROM public.single_session_bookings WHERE id = _booking_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'booking_not_found' USING ERRCODE = 'P0404'; END IF;
  PERFORM pg_advisory_xact_lock(public.single_session_slot_lock_key(_slot_start));
  SELECT * INTO _booking FROM public.single_session_bookings WHERE id = _booking_id FOR UPDATE;

  SELECT * INTO _event FROM public.booking_event_types WHERE slug = _booking.event_slug;
  IF _event.requires_payment IS DISTINCT FROM false THEN
    RAISE EXCEPTION 'payment_required' USING ERRCODE = 'P0400';
  END IF;

  IF _booking.status = 'booked' THEN
    RETURN jsonb_build_object('booking_id', _booking.id, 'status', _booking.status,
      'lifecycle_version', _booking.lifecycle_version, 'was_existing', true);
  END IF;

  IF _booking.status <> 'draft' OR _booking.lifecycle_version <> _expected_version THEN
    RAISE EXCEPTION 'stale_booking' USING ERRCODE = 'P0409';
  END IF;

  IF NULLIF(_cancel_token_hash, '') IS NULL OR NULLIF(_cancel_payload_ciphertext, '') IS NULL THEN
    RAISE EXCEPTION 'cancel_capability_required' USING ERRCODE = 'P0400';
  END IF;

  _can_book := _live_calendar_clear AND public.booking_slot_is_clear(
    _booking.start_at, _booking.end_at,
    COALESCE(_event.buffer_before_minutes, 0), COALESCE(_event.buffer_after_minutes, 0),
    _booking.id, _booking.gcal_event_id, NULL
  );

  IF NOT _can_book THEN
    UPDATE public.single_session_bookings b SET
      status = 'expired', lifecycle_version = b.lifecycle_version + 1,
      terminal_reason = 'slot_taken_before_confirm'
    WHERE b.id = _booking_id RETURNING * INTO _booking;
    IF _booking.gcal_event_id IS NOT NULL THEN
      PERFORM public.enqueue_single_session_outbox(_booking.id, 'gcal_delete', 'system', 'pending',
        'expired', _booking.lifecycle_version, NULL);
    END IF;
    RETURN jsonb_build_object('booking_id', _booking.id, 'status', _booking.status,
      'lifecycle_version', _booking.lifecycle_version, 'was_existing', false);
  END IF;

  UPDATE public.single_session_bookings b SET
    status = 'booked', lifecycle_version = b.lifecycle_version + 1,
    amount_cents = 0, currency = 'usd',
    cancel_token_hash = _cancel_token_hash, cancel_token_expires_at = b.start_at,
    terminal_reason = NULL
  WHERE b.id = _booking_id RETURNING * INTO _booking;
  _new_version := _booking.lifecycle_version;

  PERFORM public.enqueue_single_session_outbox(_booking.id, 'gcal_promote', 'system', 'pending',
    'booked', _new_version, NULL);
  PERFORM public.enqueue_single_session_outbox(_booking.id, 'email_booking_confirmation', 'booker', 'blocked',
    'booked', _new_version, _cancel_payload_ciphertext);
  PERFORM public.enqueue_single_session_outbox(_booking.id, 'email_admin_notification', 'admin', 'blocked',
    'booked', _new_version, NULL);

  RETURN jsonb_build_object('booking_id', _booking.id, 'status', _booking.status,
    'lifecycle_version', _new_version, 'was_existing', false);
END;
$function$

enforce_booking_event_shape.body:
CREATE OR REPLACE FUNCTION public.enforce_booking_event_shape()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _event record;
  _spent integer;
BEGIN
  SELECT * INTO _event
  FROM public.booking_event_types
  WHERE slug = NEW.event_slug;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown_event' USING ERRCODE = 'P0400';
  END IF;

  -- The length is the event's, not the caller's. This is the old 70-minute
  -- CHECK, generalised: a consultation is 30 minutes and a one-off link is
  -- whatever it was minted as.
  IF NEW.end_at <> NEW.start_at + make_interval(mins => _event.length_minutes) THEN
    RAISE EXCEPTION 'duration_mismatch' USING ERRCODE = 'P0400';
  END IF;

  IF _event.single_use THEN
    -- Serialise every claim against this one link, so a simultaneous pair of
    -- clicks cannot both read "unspent" and both insert. Taken before the read,
    -- released at transaction end.
    PERFORM pg_advisory_xact_lock(hashtext('one-off-booking-link:' || NEW.event_slug));

    -- Spent means a booking exists that is live or was paid. A hold holds the
    -- link (so nobody else can start one while a checkout is open); expiring or
    -- abandoning that hold releases it again. A cancelled or refunded booking
    -- stays spent -- the session was sold once, and a replacement gets a
    -- replacement link.
    SELECT count(*) INTO _spent
    FROM public.single_session_bookings b
    WHERE b.event_slug = NEW.event_slug
      AND b.status NOT IN ('expired', 'abandoned')
      -- A retry of the same request is the same booking, not a second one.
      AND b.client_idempotency_key <> NEW.client_idempotency_key;

    IF _spent > 0 THEN
      RAISE EXCEPTION 'link_already_used' USING ERRCODE = 'P0410';
    END IF;
  END IF;

  RETURN NEW;
END;
$$

set_booking_availability_overrides.body:
CREATE OR REPLACE FUNCTION public.set_booking_availability_overrides(_overrides jsonb)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  _tz text := COALESCE((SELECT timezone FROM public.booking_availability_config WHERE id = 1), 'America/Toronto');
  _today date := (now() AT TIME ZONE _tz)::date;
BEGIN
  IF jsonb_typeof(COALESCE(_overrides, '[]'::jsonb)) <> 'array' THEN
    RAISE EXCEPTION 'invalid_overrides' USING ERRCODE = 'P0400';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(COALESCE(_overrides, '[]'::jsonb)) e
    WHERE (e->>'date') IS NULL
       OR ((e->>'start_time') IS NULL) <> ((e->>'end_time') IS NULL)
       OR ((e->>'start_time') IS NOT NULL AND (e->>'end_time')::time <= (e->>'start_time')::time)
  ) THEN
    RAISE EXCEPTION 'invalid_override_range' USING ERRCODE = 'P0400';
  END IF;
  DELETE FROM public.booking_availability_overrides WHERE date >= _today;
  INSERT INTO public.booking_availability_overrides (date, start_time, end_time, note)
  SELECT (e->>'date')::date, (e->>'start_time')::time, (e->>'end_time')::time, e->>'note'
  FROM jsonb_array_elements(COALESCE(_overrides, '[]'::jsonb)) e
  WHERE (e->>'date')::date >= _today;
  RETURN public.get_booking_availability();
END;
$function$

get_single_session_status.body:
CREATE OR REPLACE FUNCTION public.get_single_session_status(
  _stripe_checkout_session_id text DEFAULT NULL,
  _booking_token_hash text DEFAULT NULL,
  _booking_id uuid DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _booking public.single_session_bookings%ROWTYPE;
  _event public.booking_event_types%ROWTYPE;
  _calendar_url text;
  _calendar_ready boolean;
BEGIN
  IF NULLIF(_booking_token_hash, '') IS NULL
     OR (NULLIF(_stripe_checkout_session_id, '') IS NULL AND _booking_id IS NULL) THEN
    RAISE EXCEPTION 'invalid_booking_token' USING ERRCODE = 'P0403';
  END IF;

  SELECT * INTO _booking
  FROM public.single_session_bookings b
  WHERE b.booking_token_hash = _booking_token_hash
    AND (
      (_booking_id IS NOT NULL AND b.id = _booking_id)
      OR (NULLIF(_stripe_checkout_session_id, '') IS NOT NULL
          AND b.stripe_checkout_session_id = _stripe_checkout_session_id)
    );
  IF NOT FOUND OR _booking.booking_token_expires_at <= now() THEN
    RAISE EXCEPTION 'invalid_booking_token' USING ERRCODE = 'P0403';
  END IF;

  SELECT * INTO _event FROM public.booking_event_types WHERE slug = _booking.event_slug;
  SELECT se.html_link INTO _calendar_url
  FROM public.schedule_events se
  WHERE se.google_event_id = _booking.gcal_event_id
    AND se.deleted_at IS NULL
  LIMIT 1;

  _calendar_ready := _booking.status = 'booked'
    AND NULLIF(_booking.meet_url, '') IS NOT NULL
    AND NULLIF(_calendar_url, '') IS NOT NULL;

  RETURN jsonb_strip_nulls(jsonb_build_object(
    'id', _booking.id,
    'booking_id', _booking.id,
    'status', _booking.status,
    'start_at', _booking.start_at,
    'end_at', _booking.end_at,
    'attendee_name', _booking.name,
    'event_label', COALESCE(_event.label, 'LSAT Session'),
    'duration_minutes', round(extract(epoch FROM (_booking.end_at - _booking.start_at)) / 60)::integer,
    'timezone', COALESCE(_booking.booker_timezone, 'America/Toronto'),
    'meet_url', CASE WHEN _booking.status = 'booked' THEN _booking.meet_url ELSE NULL END,
    'calendar_url', CASE WHEN _booking.status = 'booked' THEN _calendar_url ELSE NULL END,
    'calendar_ready', _calendar_ready,
    'calendar_pending', (_booking.status = 'booked' AND NOT _calendar_ready)
  ));
END;
$$

reconcile_single_session_calendar_deleti.body:
CREATE OR REPLACE FUNCTION public.reconcile_single_session_calendar_deletion(
  _booking_id uuid,
  _google_event_id text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _booking public.single_session_bookings%ROWTYPE;
BEGIN
  SELECT * INTO _booking
  FROM public.single_session_bookings
  WHERE id = _booking_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('outcome', 'not_found');
  END IF;
  IF _booking.gcal_event_id IS DISTINCT FROM _google_event_id THEN
    RETURN jsonb_build_object('outcome', 'event_mismatch');
  END IF;
  IF _booking.status = 'cancelled' THEN
    RETURN jsonb_build_object('outcome', 'already_cancelled');
  END IF;
  IF _booking.status <> 'booked' THEN
    RETURN jsonb_build_object('outcome', 'ignored', 'status', _booking.status);
  END IF;

  UPDATE public.single_session_bookings b
  SET status = 'cancelled',
      lifecycle_version = b.lifecycle_version + 1,
      terminal_reason = 'google_calendar_deleted'
  WHERE b.id = _booking.id
  RETURNING * INTO _booking;

  UPDATE public.single_session_outbox
  SET state = 'superseded', updated_at = now()
  WHERE booking_id = _booking.id
    AND state IN ('blocked', 'pending', 'failed')
    AND action IN ('gcal_promote', 'email_booking_confirmation', 'email_admin_notification');

  RETURN jsonb_build_object(
    'outcome', 'cancelled',
    'booking_id', _booking.id,
    'lifecycle_version', _booking.lifecycle_version
  );
END;
$$

guard_conditional_practice_run.body:
create or replace function public.guard_conditional_practice_run()
returns trigger language plpgsql set search_path = public as $$
begin
  if new.id is distinct from old.id or new.user_id is distinct from old.user_id
    or new.snapshot is distinct from old.snapshot or new.created_at is distinct from old.created_at then
    raise exception 'Practice identity and question snapshot cannot change';
  end if;
  if new.revision <> old.revision + 1 then
    raise exception 'Practice revision must advance by one';
  end if;
  -- Submissions are append-only. Cursor/choice/reveal state may change, but
  -- an original answer cannot disappear when a student retries a question.
  if jsonb_array_length(new.state->'answers') < jsonb_array_length(old.state->'answers')
    or exists (
      select 1 from jsonb_array_elements(old.state->'answers') with ordinality as answer(value, n)
      where answer.value is distinct from (new.state->'answers')->(answer.n::integer - 1)
    ) then raise exception 'Earlier practice answers must be preserved'; end if;
  new.updated_at := now();
  return new;
end;
$$

snapshot_deleted_student.body:
CREATE OR REPLACE FUNCTION public.snapshot_deleted_student()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO public.deleted_students (user_id, email, display_name, deleted_at)
  VALUES (
    OLD.id,
    OLD.email,
    (SELECT display_name FROM public.profiles WHERE class_id = OLD.id::text),
    now()
  )
  ON CONFLICT (user_id) DO UPDATE
    SET email = EXCLUDED.email,
        display_name = COALESCE(EXCLUDED.display_name, public.deleted_students.display_name),
        deleted_at = EXCLUDED.deleted_at;

  UPDATE public.student_sessions          SET former_student_id = OLD.id WHERE student_id = OLD.id;
  UPDATE public.booking_passes            SET former_student_id = OLD.id WHERE student_id = OLD.id;
  UPDATE public.booking_commerce_events   SET former_student_id = OLD.id WHERE student_id = OLD.id;
  UPDATE public.single_session_bookings   SET former_student_id = OLD.id WHERE user_id    = OLD.id;
  UPDATE public.external_booking_events   SET former_student_id = OLD.id WHERE student_id = OLD.id;

  RETURN OLD;
END;
$function$

profiles_access_tier_drift.body:
CREATE OR REPLACE FUNCTION public.profiles_access_tier_drift()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  practice boolean;
BEGIN
  -- Archive/unarchive remembers the tier without reopening any access.
  IF NEW.archived_at IS NOT NULL OR NEW.archived_at IS DISTINCT FROM OLD.archived_at THEN
    RETURN NEW;
  END IF;

  IF NEW.access_tier IS DISTINCT FROM OLD.access_tier AND NEW.access_tier IS NOT NULL THEN
    NEW.has_drill_access := NEW.access_tier = 'tier_1';
    NEW.has_practice_access := NEW.access_tier = 'tier_1';
    NEW.has_classroom_access := NEW.access_tier IN ('tier_1', 'tier_2');
    NEW.has_chat_access := true;
    NEW.has_schedule_access := true;
  ELSIF NOT (
    NEW.has_drill_access IS DISTINCT FROM OLD.has_drill_access OR
    NEW.has_practice_access IS DISTINCT FROM OLD.has_practice_access OR
    NEW.has_classroom_access IS DISTINCT FROM OLD.has_classroom_access OR
    NEW.has_chat_access IS DISTINCT FROM OLD.has_chat_access OR
    NEW.has_schedule_access IS DISTINCT FROM OLD.has_schedule_access OR
    NEW.has_journal_access IS DISTINCT FROM OLD.has_journal_access OR
    NEW.has_flagged_access IS DISTINCT FROM OLD.has_flagged_access OR
    NEW.has_analytics_access IS DISTINCT FROM OLD.has_analytics_access OR
    NEW.has_activity_access IS DISTINCT FROM OLD.has_activity_access OR
    NEW.has_bootcamp_access IS DISTINCT FROM OLD.has_bootcamp_access OR
    NEW.has_ta_access IS DISTINCT FROM OLD.has_ta_access OR
    NEW.has_export_access IS DISTINCT FROM OLD.has_export_access OR
    NEW.has_waj_access IS DISTINCT FROM OLD.has_waj_access
  ) THEN
    -- Presence and other profile edits must not change access.
    RETURN NEW;
  END IF;

  practice := COALESCE(NEW.has_drill_access, false) OR COALESCE(NEW.has_practice_access, false);
  NEW.has_journal_access := practice;
  NEW.has_flagged_access := practice;
  NEW.has_analytics_access := practice;
  NEW.has_waj_access := false;
  NEW.has_activity_access := false;
  NEW.has_bootcamp_access := false;
  NEW.has_ta_access := false;
  NEW.has_export_access := false;
  IF NEW.access_tier = 'tier_1' AND NOT (
    NEW.has_drill_access AND NEW.has_practice_access AND NEW.has_classroom_access AND
    NEW.has_chat_access AND NEW.has_schedule_access
  ) THEN
    NEW.access_tier := 'tier_2';
  ELSIF NEW.access_tier = 'tier_3' AND (
    NEW.has_drill_access OR NEW.has_practice_access OR NEW.has_classroom_access OR
    NOT NEW.has_chat_access OR NOT NEW.has_schedule_access
  ) THEN
    NEW.access_tier := 'tier_2';
  END IF;
  RETURN NEW;
END;
$function$

admin_link_stripe_payment.body:
CREATE OR REPLACE FUNCTION public.admin_link_stripe_payment(_payment_id uuid, _student_id uuid)
RETURNS public.stripe_payments
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE _row public.stripe_payments%ROWTYPE;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN RAISE EXCEPTION 'forbidden'; END IF;
  UPDATE public.stripe_payments
    SET student_id = _student_id,
        match_state = CASE WHEN _student_id IS NULL THEN 'ignored' ELSE 'linked' END,
        grant_state = CASE
          WHEN grant_state = 'none' AND offer_id IS NOT NULL AND _student_id IS NOT NULL AND status = 'succeeded' THEN 'awaiting'
          ELSE grant_state END,
        updated_at = now()
    WHERE id = _payment_id RETURNING * INTO _row;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown_payment'; END IF;
  RETURN _row;
END;
$$

admin_grant_stripe_payment.body:
CREATE OR REPLACE FUNCTION public.admin_grant_stripe_payment(_payment_id uuid)
RETURNS public.stripe_payments
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN RAISE EXCEPTION 'forbidden'; END IF;
  RETURN public.grant_stripe_package_locked(_payment_id, auth.uid());
END;
$$

admin_dismiss_stripe_payment.body:
CREATE OR REPLACE FUNCTION public.admin_dismiss_stripe_payment(_payment_id uuid)
RETURNS public.stripe_payments
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE _row public.stripe_payments%ROWTYPE;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN RAISE EXCEPTION 'forbidden'; END IF;
  UPDATE public.stripe_payments
    SET grant_state = CASE WHEN grant_state = 'awaiting' THEN 'dismissed' ELSE grant_state END,
        match_state = CASE WHEN match_state = 'unmatched' THEN 'ignored' ELSE match_state END,
        updated_at = now()
    WHERE id = _payment_id RETURNING * INTO _row;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown_payment'; END IF;
  RETURN _row;
END;
$$

activity_ai_source_v1.body:
create function public.activity_ai_source_v1(p_owner uuid,p_kind text,p_source uuid,p_order integer,p_response text,p_attempt integer)
returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare profile jsonb; source jsonb; item jsonb; matches integer; canonical jsonb; first_confirmed boolean; trusted_ideas jsonb; trusted_coach jsonb;
begin
 select to_jsonb(p) into profile from public.profiles p where p.class_id=p_owner::text for share;
 if profile is null or not profile ? 'archived_at' or profile->>'archived_at' is not null then return null; end if;
 if p_kind='assignment' then
  select to_jsonb(a) into source from public.activity_assignments a where a.id=p_source and a.student_id=p_owner for share;
  if source is null or not source ? 'revoked_at' or source->>'revoked_at' is not null
    or source->>'status' is null or source->>'status' not in ('assigned','in_progress','completed') then return null; end if;
 elsif p_kind='preview' then
  perform 1 from public.user_roles where user_id=p_owner and role::text='admin' for share;
  if not found then return null; end if;
  select to_jsonb(a) into source from public.activities a where a.id=p_source and a.created_by=p_owner for share;
  if source is null then return null; end if;
 else return null; end if;
 if source->>'item_format' is null or source->>'item_format' not in ('free-text','variation','mcq') or jsonb_typeof(source->'items') is distinct from 'array' then return null; end if;
 trusted_coach:=source->'instructions'->'coach';
 -- Only absent/null briefs may use the original legacy negation rubric.
 -- A supplied malformed brief must never silently change the skill graded.
 if trusted_coach is not null and trusted_coach<>'null'::jsonb then
  if jsonb_typeof(trusted_coach) is distinct from 'object'
    or jsonb_typeof(trusted_coach->'drill') is distinct from 'string'
    or length(btrim(trusted_coach->>'drill'))<1 or length(trusted_coach->>'drill')>1000
    or jsonb_typeof(trusted_coach->'rubric') is distinct from 'array' then return null; end if;
  if jsonb_array_length(trusted_coach->'rubric') not between 1 and 50
    or exists(select 1 from jsonb_array_elements(trusted_coach->'rubric') v where jsonb_typeof(v) is distinct from 'string'
      or length(btrim(v#>>'{}'))<1 or length(v#>>'{}')>4000)
    or (trusted_coach ? 'partial_rule' and (jsonb_typeof(trusted_coach->'partial_rule') is distinct from 'string'
      or length(trusted_coach->>'partial_rule')>4000))
    or length(trusted_coach::text)>24000 then return null; end if;
 end if;
 if exists(select 1 from jsonb_array_elements(source->'items') v where jsonb_typeof(v) is distinct from 'object'
   or jsonb_typeof(v->'order') is distinct from 'number' or coalesce(v->>'order','') !~ '^[1-9][0-9]{0,8}$') then return null; end if;
 select count(*) into matches from jsonb_array_elements(source->'items') v where v->>'order'=p_order::text;
 if matches<>1 then return null; end if;
 select v into item from jsonb_array_elements(source->'items') v where v->>'order'=p_order::text;
 if jsonb_typeof(item->'prompt') is distinct from 'string' or length(btrim(item->>'prompt'))<1 or length(item->>'prompt')>12000
  or jsonb_typeof(item->'credited_answers') is distinct from 'array' or jsonb_array_length(item->'credited_answers') not between 1 and 20
  or exists(select 1 from jsonb_array_elements(item->'credited_answers') v where jsonb_typeof(v)<>'string' or length(btrim(v#>>'{}'))<1 or length(v#>>'{}')>4000)
  or length((item->'credited_answers')::text)>20000 or length(coalesce(item->>'explanation',''))>12000
  or length(coalesce(source->'instructions'->'coach','{}'::jsonb)::text)>24000 then return null; end if;
 first_confirmed:=false;
 if p_attempt=2 then
  select exists(select 1 from public.activity_ai_receipts_v1 r where r.owner_id=p_owner and r.source_kind=p_kind
   and r.source_id=p_source and r.item_order=p_order and r.attempt_no=1 and r.state='completed'
   and r.canonical_payload->>'statement' is not distinct from item->>'prompt'
   and r.canonical_payload->'creditedAnswers' is not distinct from item->'credited_answers'
   and r.canonical_payload->>'explanation' is not distinct from coalesce(item->>'explanation','')
   and r.canonical_payload->>'category' is not distinct from item->>'category'
   and r.canonical_payload->'coach' is not distinct from coalesce(source->'instructions'->'coach','null'::jsonb)
   and (p_kind='preview' or exists(select 1 from public.activity_item_responses a where a.assignment_id=p_source and a.student_id=p_owner
     and a.item_order=p_order and a.attempt_no=1 and a.response_text=r.canonical_payload->>'studentResponse' and a.verdict=r.result->>'verdict')))
  into first_confirmed;
  if not first_confirmed then return null; end if;
 end if;
 canonical:=jsonb_build_object('statement',item->>'prompt','creditedAnswers',item->'credited_answers',
  'explanation',coalesce(item->>'explanation',''),'category',item->>'category','coach',source->'instructions'->'coach',
  'studentResponse',p_response,'attemptNo',p_attempt,'sourceKind',p_kind,'sourceId',p_source,'itemOrder',p_order,
  'firstAttemptConfirmed',first_confirmed);
 -- Press checklists are authored in the trusted explanation (same numbered
 -- separators as parsePress). Never accept an independent client checklist.
 trusted_ideas:=item->'ideas';
 if trusted_ideas is null and position('the big ideas' in lower(coalesce(item->>'explanation','')))>0 then
  select jsonb_agg(jsonb_build_object('n',m[1]::integer,'text',regexp_replace(btrim(m[2]),'[[:space:]]*[.]$','')) order by m[1]::integer)
   into trusted_ideas from regexp_matches(regexp_replace(item->>'explanation','[.][[:space:]]*Named traps:.*$','','i'),'[(]([0-9])[)][[:space:]]*([^·]+?)(?=[[:space:]]*·|$)','g') m;
 end if;
 if trusted_ideas is not null then
  if jsonb_typeof(trusted_ideas) is distinct from 'array' or jsonb_array_length(trusted_ideas) not between 1 and 100
   or exists(select 1 from jsonb_array_elements(trusted_ideas) idea where jsonb_typeof(idea) is distinct from 'object'
     or jsonb_typeof(idea->'n') is distinct from 'number' or coalesce(idea->>'n','') !~ '^[1-9][0-9]{0,5}$' or jsonb_typeof(idea->'text') is distinct from 'string'
     or length(btrim(idea->>'text'))<1 or length(idea->>'text')>2000)
   or (select count(*) from jsonb_array_elements(trusted_ideas))<>(select count(distinct idea->>'n') from jsonb_array_elements(trusted_ideas) idea) then return null; end if;
  canonical:=canonical||jsonb_build_object('ideas',trusted_ideas);
 end if;
 if length(canonical::text)>64000 then return null; end if;
 return canonical;
end $$

begin_activity_ai_request_v1.body:
create function public.begin_activity_ai_request_v1(p_owner_id uuid,p_request_id uuid,p_source_kind text,p_source_id uuid,p_item_order integer,p_student_response text,p_attempt_no integer)
returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare r public.activity_ai_receipts_v1; k public.activity_ai_request_keys_v1; c public.activity_ai_configuration_v1;
 payload jsonb; digest text; at_time timestamptz; minute_start timestamptz; day_start timestamptz; active_count integer;
begin
 if p_owner_id is null or p_request_id is null or p_source_id is null or p_item_order is null or p_item_order<1
  or p_source_kind is null or p_source_kind not in ('assignment','preview') or p_attempt_no is null or p_attempt_no not between 1 and 2
  or p_student_response is null or length(btrim(p_student_response))<1 or length(p_student_response)>10000 or octet_length(p_student_response)>40000 then
  return public.activity_ai_reply_v1(p_request_id,r,'denied',422,'invalid_request'); end if;
 perform pg_advisory_xact_lock(hashtextextended('activity-ai-global-v1',0));
 perform pg_advisory_xact_lock(hashtextextended('activity-ai-owner-v1:'||p_owner_id::text,0));
 payload:=public.activity_ai_source_v1(p_owner_id,p_source_kind,p_source_id,p_item_order,p_student_response,p_attempt_no);
 if payload is null then return public.activity_ai_reply_v1(p_request_id,r,'denied',403,'source_unavailable'); end if;
 digest:=encode(sha256(convert_to(payload::text,'UTF8')),'hex');
 select * into k from public.activity_ai_request_keys_v1 where request_id=p_request_id;
 if found then
  if k.owner_id<>p_owner_id or k.payload_sha256<>digest then return public.activity_ai_reply_v1(p_request_id,r,'denied',409,'request_conflict'); end if;
  select * into r from public.activity_ai_receipts_v1 where id=k.receipt_id for update;
 else
  select * into r from public.activity_ai_receipts_v1 where owner_id=p_owner_id and payload_sha256=digest for update;
  if found then insert into public.activity_ai_request_keys_v1 values(p_request_id,p_owner_id,r.id,digest,clock_timestamp()); end if;
 end if;
 if r.id is not null and r.canonical_payload<>payload then return public.activity_ai_reply_v1(p_request_id,r,'denied',409,'request_conflict'); end if;
 if r.state='completed' then return public.activity_ai_reply_v1(p_request_id,r,'cached',200,'cached'); end if;
 if r.state='failed' then return public.activity_ai_reply_v1(p_request_id,r,'failed',502,'request_failed'); end if;
 at_time:=clock_timestamp();
 if r.state in ('dispatched','uncertain') then
  if r.state='dispatched' and r.lease_expires_at<=at_time then update public.activity_ai_receipts_v1 set state='uncertain' where id=r.id returning * into r; end if;
  return public.activity_ai_reply_v1(p_request_id,r,case when r.state='uncertain' then 'uncertain' else 'in_flight' end,409,case when r.state='uncertain' then 'dispatch_uncertain' else 'request_in_flight' end);
 end if;
 if r.state='reserved' and r.lease_expires_at>at_time then return public.activity_ai_reply_v1(p_request_id,r,'in_flight',409,'request_in_flight'); end if;
 select * into c from public.activity_ai_configuration_v1 where singleton for share;
 if not coalesce(c.enabled,false) then return public.activity_ai_reply_v1(p_request_id,r,'denied',503,'contract_disabled'); end if;
 -- Unknown dispatched outcomes count against concurrency until explicitly
 -- finished by the original claim; they never expire into an automatic retry.
 update public.activity_ai_receipts_v1 set state='uncertain' where owner_id=p_owner_id and state='dispatched' and lease_expires_at<=at_time;
 select count(*) into active_count from public.activity_ai_receipts_v1 where owner_id=p_owner_id
  and (state in ('dispatched','uncertain') or (state='reserved' and lease_expires_at>at_time));
 if active_count>=c.actor_concurrency then return public.activity_ai_reply_v1(p_request_id,r,'denied',429,'concurrency_limited'); end if;
 if r.id is not null then
  update public.activity_ai_receipts_v1 set claim_id=gen_random_uuid(),lease_expires_at=at_time+interval '30 seconds' where id=r.id returning * into r;
  return public.activity_ai_reply_v1(p_request_id,r,'reserved',200,'reserved');
 end if;
 minute_start:=date_trunc('minute',at_time at time zone 'UTC') at time zone 'UTC';
 day_start:=date_trunc('day',at_time at time zone 'UTC') at time zone 'UTC';
 if coalesce((select admissions from public.activity_ai_budget_buckets_v1 where kind='actor-minute' and actor_key=p_owner_id::text and bucket_start=minute_start),0)>=c.actor_minute
  or coalesce((select admissions from public.activity_ai_budget_buckets_v1 where kind='actor-day' and actor_key=p_owner_id::text and bucket_start=day_start),0)>=c.actor_day
  or coalesce((select admissions from public.activity_ai_budget_buckets_v1 where kind='global-day' and actor_key='global' and bucket_start=day_start),0)>=c.global_day then
  return public.activity_ai_reply_v1(p_request_id,r,'denied',429,'rate_limited'); end if;
 insert into public.activity_ai_budget_buckets_v1 values('actor-minute',p_owner_id::text,minute_start,1),('actor-day',p_owner_id::text,day_start,1),('global-day','global',day_start,1)
 on conflict(kind,actor_key,bucket_start) do update set admissions=activity_ai_budget_buckets_v1.admissions+1;
 insert into public.activity_ai_receipts_v1(id,owner_id,source_kind,source_id,item_order,attempt_no,canonical_payload,payload_sha256,state,claim_id,lease_expires_at,admitted_at)
 values(p_request_id,p_owner_id,p_source_kind,p_source_id,p_item_order,p_attempt_no,payload,digest,'reserved',gen_random_uuid(),at_time+interval '30 seconds',at_time) returning * into r;
 insert into public.activity_ai_request_keys_v1 values(p_request_id,p_owner_id,r.id,digest,at_time);
 return public.activity_ai_reply_v1(p_request_id,r,'reserved',200,'reserved');
end $$

dispatch_activity_ai_request_v1.body:
create function public.dispatch_activity_ai_request_v1(p_owner_id uuid,p_request_id uuid,p_claim_id uuid)
returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare r public.activity_ai_receipts_v1; payload jsonb; c public.activity_ai_configuration_v1;
begin
 perform pg_advisory_xact_lock(hashtextextended('activity-ai-global-v1',0));
 perform pg_advisory_xact_lock(hashtextextended('activity-ai-owner-v1:'||coalesce(p_owner_id::text,''),0));
 select r1.* into r from public.activity_ai_request_keys_v1 k join public.activity_ai_receipts_v1 r1 on r1.id=k.receipt_id
 where k.request_id=p_request_id and k.owner_id=p_owner_id for update of r1;
 if r.id is null or p_claim_id is null or r.claim_id<>p_claim_id then return public.activity_ai_reply_v1(p_request_id,r,'denied',409,'claim_conflict'); end if;
 payload:=public.activity_ai_source_v1(r.owner_id,r.source_kind,r.source_id,r.item_order,r.canonical_payload->>'studentResponse',r.attempt_no);
 if payload is null then return public.activity_ai_reply_v1(p_request_id,r,'denied',403,'source_unavailable'); end if;
 if payload<>r.canonical_payload then return public.activity_ai_reply_v1(p_request_id,r,'denied',409,'source_changed'); end if;
 if r.state='completed' then return public.activity_ai_reply_v1(p_request_id,r,'cached',200,'cached'); end if;
 if r.state in ('dispatched','uncertain') then
  if r.state='dispatched' and r.lease_expires_at<=clock_timestamp() then update public.activity_ai_receipts_v1 set state='uncertain' where id=r.id returning * into r; end if;
  return public.activity_ai_reply_v1(p_request_id,r,case when r.state='uncertain' then 'uncertain' else 'in_flight' end,409,'dispatch_not_repeatable'); end if;
 if r.state<>'reserved' or r.lease_expires_at<=clock_timestamp() then return public.activity_ai_reply_v1(p_request_id,r,'denied',409,'claim_expired'); end if;
 select * into c from public.activity_ai_configuration_v1 where singleton for share;
 if not coalesce(c.enabled,false) then return public.activity_ai_reply_v1(p_request_id,r,'denied',503,'contract_disabled'); end if;
 update public.activity_ai_receipts_v1 set state='dispatched',dispatched_at=clock_timestamp(),lease_expires_at=clock_timestamp()+interval '30 seconds'
 where id=r.id and state='reserved' and claim_id=p_claim_id returning * into r;
 return public.activity_ai_reply_v1(p_request_id,r,'dispatched',200,'dispatched');
end $$

finish_activity_ai_request_v1.body:
create function public.finish_activity_ai_request_v1(p_owner_id uuid,p_request_id uuid,p_claim_id uuid,p_result jsonb default null,p_failure_category text default null)
returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare r public.activity_ai_receipts_v1; payload jsonb; clean jsonb; coverage jsonb;
begin
 perform pg_advisory_xact_lock(hashtextextended('activity-ai-global-v1',0));
 perform pg_advisory_xact_lock(hashtextextended('activity-ai-owner-v1:'||coalesce(p_owner_id::text,''),0));
 select r1.* into r from public.activity_ai_request_keys_v1 k join public.activity_ai_receipts_v1 r1 on r1.id=k.receipt_id
 where k.request_id=p_request_id and k.owner_id=p_owner_id for update of r1;
 if r.id is null or p_claim_id is null or r.claim_id<>p_claim_id then return public.activity_ai_reply_v1(p_request_id,r,'denied',409,'claim_conflict'); end if;
 if r.state='completed' then
  payload:=public.activity_ai_source_v1(r.owner_id,r.source_kind,r.source_id,r.item_order,r.canonical_payload->>'studentResponse',r.attempt_no);
  if payload is null then return public.activity_ai_reply_v1(p_request_id,r,'denied',403,'source_unavailable'); end if;
  if payload<>r.canonical_payload then return public.activity_ai_reply_v1(p_request_id,r,'denied',409,'source_changed'); end if;
  if p_failure_category is null and p_result=r.result then return public.activity_ai_reply_v1(p_request_id,r,'cached',200,'cached'); end if;
  return public.activity_ai_reply_v1(p_request_id,r,'denied',409,'finish_conflict'); end if;
 if r.state='failed' then return public.activity_ai_reply_v1(p_request_id,r,'failed',502,'request_failed'); end if;
 if r.state not in ('dispatched','uncertain') then return public.activity_ai_reply_v1(p_request_id,r,'denied',409,'not_dispatched'); end if;
 payload:=public.activity_ai_source_v1(r.owner_id,r.source_kind,r.source_id,r.item_order,r.canonical_payload->>'studentResponse',r.attempt_no);
 if payload is null then p_result:=null;p_failure_category:='access_revoked';
 elsif payload<>r.canonical_payload then p_result:=null;p_failure_category:='source_changed'; end if;
 if p_failure_category is not null then
  if p_result is not null or p_failure_category not in ('provider_error','timeout','malformed_result','transport_error','cancelled','access_revoked','source_changed','uncertain') then
   return public.activity_ai_reply_v1(p_request_id,r,'denied',422,'invalid_finish'); end if;
  update public.activity_ai_receipts_v1 set state=case when p_failure_category='uncertain' then 'uncertain' else 'failed' end,
   failure_category=p_failure_category,finished_at=case when p_failure_category='uncertain' then null else clock_timestamp() end where id=r.id returning * into r;
  return public.activity_ai_reply_v1(p_request_id,r,case when r.state='uncertain' then 'uncertain' else 'failed' end,502,case when r.state='uncertain' then 'dispatch_uncertain' else 'request_failed' end); end if;
 if jsonb_typeof(p_result) is distinct from 'object' or p_result->>'verdict' is null or p_result->>'verdict' not in ('correct','partial','incorrect')
  or jsonb_typeof(p_result->'feedback') is distinct from 'string' or length(btrim(p_result->>'feedback'))<1 or length(p_result->>'feedback')>2000
  or exists(select 1 from jsonb_object_keys(p_result) key where key not in ('verdict','feedback','covered')) then
  return public.activity_ai_reply_v1(p_request_id,r,'denied',422,'invalid_result'); end if;
 clean:=jsonb_build_object('verdict',p_result->>'verdict','feedback',p_result->>'feedback');
 if p_result ? 'covered' then
  if jsonb_typeof(p_result->'covered') is distinct from 'array' or jsonb_array_length(p_result->'covered')>100
    or exists(select 1 from jsonb_array_elements(p_result->'covered') v where jsonb_typeof(v)<>'number' or v::text !~ '^[1-9][0-9]{0,5}$')
    or jsonb_typeof(r.canonical_payload->'ideas') is distinct from 'array'
    or exists(select 1 from jsonb_array_elements(p_result->'covered') v where not exists(select 1 from jsonb_array_elements(r.canonical_payload->'ideas') idea where idea->'n'=v)) then
   return public.activity_ai_reply_v1(p_request_id,r,'denied',422,'invalid_coverage'); end if;
  -- Retain the validated envelope exactly, making identical finish retries
  -- replayable even if a service caller supplied repeated checklist numbers.
  clean:=clean||jsonb_build_object('covered',p_result->'covered');
 end if;
 update public.activity_ai_receipts_v1 set state='completed',result=clean,failure_category=null,finished_at=clock_timestamp() where id=r.id returning * into r;
 return public.activity_ai_reply_v1(p_request_id,r,'completed',200,'completed');
end $$

grant_stripe_package_locked.body:
CREATE OR REPLACE FUNCTION public.grant_stripe_package_locked(_payment_id uuid, _actor uuid)
RETURNS public.stripe_payments
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  _row public.stripe_payments%ROWTYPE;
  _offer public.booking_offers%ROWTYPE;
  _pass public.booking_passes%ROWTYPE;
  _creator uuid;
BEGIN
  SELECT * INTO _row FROM public.stripe_payments WHERE id = _payment_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown_payment'; END IF;
  IF _row.grant_state <> 'awaiting' THEN RETURN _row; END IF;
  IF _row.student_id IS NULL THEN RAISE EXCEPTION 'link_a_student_first'; END IF;
  IF _row.status <> 'succeeded' OR _row.amount_refunded_cents <> 0 THEN RAISE EXCEPTION 'payment_not_settled'; END IF;
  SELECT * INTO _offer FROM public.booking_offers WHERE id = _row.offer_id AND provider = 'stripe';
  IF NOT FOUND OR _offer.credits <= 0 THEN RAISE EXCEPTION 'not_a_package_offer'; END IF;

  -- Different payments for a student also serialize, including their first pass.
  PERFORM pg_advisory_xact_lock(hashtextextended(_row.student_id::text, 0));
  SELECT * INTO _pass FROM public.booking_passes WHERE student_id = _row.student_id ORDER BY created_at DESC, id DESC LIMIT 1 FOR UPDATE;
  IF FOUND THEN
    UPDATE public.booking_passes SET total_credits = total_credits + _offer.credits, status = 'active', expires_at = NULL WHERE id = _pass.id;
  ELSE
    SELECT user_id INTO _creator FROM public.user_roles WHERE role = 'admin' ORDER BY user_id LIMIT 1;
    _creator := COALESCE(_actor, _creator);
    IF _creator IS NULL THEN RAISE EXCEPTION 'pass_creator_missing'; END IF;
    INSERT INTO public.booking_passes (student_id, student_email, student_name, total_credits, used_credits, session_length_minutes, status, token_hash, created_by)
      VALUES (_row.student_id, _row.email, COALESCE(_row.payer_name, _row.email, 'Student'), _offer.credits, 0, 70, 'active',
        encode(sha256(convert_to(gen_random_uuid()::text, 'UTF8')), 'hex'), _creator);
  END IF;
  INSERT INTO public.booking_commerce_events (student_id, offer_id, provider, provider_event_id, event_type, email, amount_cents, currency)
    VALUES (_row.student_id, _row.offer_id, 'stripe', 'charge:' || _row.stripe_charge_id, 'paid', _row.email, _row.amount_cents, _row.currency)
    ON CONFLICT (provider, provider_event_id, event_type) DO NOTHING;
  UPDATE public.stripe_payments SET grant_state = 'granted', granted_credits = _offer.credits, granted_at = now(), granted_by = _actor, updated_at = now()
    WHERE id = _payment_id RETURNING * INTO _row;
  RETURN _row;
END;
$$

auto_grant_stripe_payment.body:
CREATE OR REPLACE FUNCTION public.auto_grant_stripe_payment(_charge_id text, _checkout_session_id text, _student_id uuid, _offer_id text)
RETURNS public.stripe_payments
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE _row public.stripe_payments%ROWTYPE;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'forbidden'; END IF;
  SELECT * INTO _row FROM public.stripe_payments WHERE stripe_charge_id = _charge_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown_payment'; END IF;
  IF _row.grant_state <> 'awaiting' THEN RETURN _row; END IF;
  IF NOT _row.auto_grant_eligible OR _row.source <> 'webhook' OR _row.match_state <> 'matched'
     OR _row.checkout_session_id IS DISTINCT FROM _checkout_session_id
     OR _row.student_id IS DISTINCT FROM _student_id OR _row.offer_id IS DISTINCT FROM _offer_id
     OR NOT EXISTS (SELECT 1 FROM public.booking_offers WHERE id = _offer_id AND active AND provider = 'stripe')
  THEN RETURN _row; END IF;
  RETURN public.grant_stripe_package_locked(_row.id, NULL);
END;
$$

has_reading_center_access.body:
create or replace function public.has_reading_center_access()
returns boolean language sql stable security definer set search_path = public
as $$
  select auth.uid() is not null and (
    public.has_role(auth.uid(), 'admin') or exists (
      select 1 from public.classroom_items ci
      where ci.student_id = auth.uid() and ci.type = 'activity'
        and ci.source_table = 'reading_center' and ci.source_id = 'library'
        and ci.visible_to_student and ci.status in ('assigned','in_progress','completed')
        and (ci.unlock_at is null or ci.unlock_at <= now())
    )
  );
$$

assign_reading_center.body:
create or replace function public.assign_reading_center(
  p_student_id uuid, p_unlock_at timestamptz default null,
  p_title text default 'Reading Center',
  p_description text default 'Practice reading articles with five reading modes, bookmarks and reading goals.'
) returns jsonb language plpgsql security definer set search_path = public
as $$
declare v_item public.classroom_items%rowtype;
begin
  if auth.uid() is null or not public.has_role(auth.uid(),'admin') then
    raise exception 'Only an administrator may assign Reading Center' using errcode = '42501';
  end if;
  if not exists (select 1 from auth.users where id = p_student_id) then
    raise exception 'Student account not found' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('reading-center:' || p_student_id::text, 0));
  select * into v_item from public.classroom_items
    where student_id = p_student_id and type = 'activity'
      and source_table = 'reading_center' and source_id = 'library'
      and visible_to_student and status in ('assigned','in_progress','completed')
    limit 1;
  if found then return jsonb_build_object('item',to_jsonb(v_item),'reused',true); end if;
  insert into public.classroom_items (
    student_id,class_id,created_by,type,title,description,source_table,source_id,
    status,visible_to_student,unlock_at,metadata_json
  ) values (
    p_student_id,p_student_id,auth.uid(),'activity',coalesce(nullif(trim(p_title),''),'Reading Center'),
    p_description,'reading_center','library','assigned',true,p_unlock_at,
    jsonb_build_object('assigned_route','/reading-center')
  ) returning * into v_item;
  return jsonb_build_object('item',to_jsonb(v_item),'reused',false);
end;
$$

revoke_reading_center.body:
create or replace function public.revoke_reading_center(p_student_id uuid)
returns void language plpgsql security definer set search_path = public
as $$
begin
  if auth.uid() is null or not public.has_role(auth.uid(),'admin') then
    raise exception 'Only an administrator may remove Reading Center access' using errcode = '42501';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('reading-center:' || p_student_id::text, 0));
  update public.classroom_items set visible_to_student=false,status='archived'
    where student_id=p_student_id and source_table='reading_center' and source_id='library'
      and (visible_to_student or status <> 'archived');
end;
$$

reading_center_rename_tag.body:
create or replace function public.reading_center_rename_tag(p_old_name text,p_new_name text,p_color int)
returns void language plpgsql security invoker set search_path=public
as $$
declare v_name text := trim(p_new_name);
begin
  if not public.has_reading_center_access() then
    raise exception 'Reading Center is not assigned' using errcode='42501';
  end if;
  if v_name is null or length(v_name) not between 1 and 100 then
    raise exception 'Choose a tag name between 1 and 100 characters' using errcode='22023';
  end if;
  if p_color is null or p_color not between 0 and 24 then
    raise exception 'Choose a valid tag color' using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('reading-center-tags:' || auth.uid()::text,0));
  if not exists(select 1 from public.reading_center_tags where user_id=auth.uid() and name=p_old_name) then
    raise exception 'Tag not found' using errcode='22023';
  end if;
  if v_name=p_old_name then
    update public.reading_center_tags set color=p_color where user_id=auth.uid() and name=p_old_name;
    return;
  end if;
  if exists(select 1 from public.reading_center_tags where user_id=auth.uid() and name=v_name) then
    raise exception 'A tag with that name already exists' using errcode='23505';
  end if;
  -- A direct concurrent tag creation is also protected by the unique key.
  -- No conflict overwrite is allowed, so a collision rolls back the rename.
  insert into public.reading_center_tags(user_id,name,color) values(auth.uid(),v_name,p_color);
  update public.reading_center_passage_metadata set tags=array(
    select distinct x from unnest(array_replace(tags,p_old_name,v_name)) as x
  ) where user_id=auth.uid() and p_old_name=any(tags);
  delete from public.reading_center_tags where user_id=auth.uid() and name=p_old_name;
end;
$$

reading_center_delete_tag.body:
create or replace function public.reading_center_delete_tag(p_name text)
returns void language plpgsql security invoker set search_path=public
as $$
begin
  if not public.has_reading_center_access() then raise exception 'Reading Center is not assigned' using errcode='42501'; end if;
  update public.reading_center_passage_metadata set tags=array_remove(tags,p_name)
    where user_id=auth.uid() and p_name=any(tags);
  delete from public.reading_center_tags where user_id=auth.uid() and name=p_name;
end;
$$

guard_activity_mirror_access.body:
create or replace function public.guard_activity_mirror_access()
returns trigger language plpgsql security definer set search_path=public
as $function$
declare v_revoked timestamptz; v_student uuid; v_activity boolean;
begin
  if NEW.type='activity' and NEW.source_table='reading_center' and NEW.source_id='library' then
    if auth.uid() is not null and public.has_role(auth.uid(),'admin') then
      return NEW;
    end if;
    -- Student progress may advance an existing grant. Other triggers enforce
    -- the allowed statuses; this exception never creates or rebinds access.
    if TG_OP='UPDATE' and OLD.type='activity' and OLD.source_table='reading_center' and OLD.source_id='library'
      and NEW.student_id is not distinct from OLD.student_id
      and NEW.created_by is not distinct from OLD.created_by
      and NEW.visible_to_student is not distinct from OLD.visible_to_student
      and NEW.unlock_at is not distinct from OLD.unlock_at then
      return NEW;
    end if;
  end if;
  v_activity := NEW.source_table = 'activity_assignments' or NEW.type = 'activity';
  -- Existing orphan mirrors are historical data. Unrelated edits do not grant
  -- access; newly visible or rebound mirrors must satisfy the source gate.
  if TG_OP = 'UPDATE' then
    v_activity := coalesce(v_activity,false) or OLD.source_table = 'activity_assignments' or OLD.type = 'activity';
    if NEW.visible_to_student is not distinct from OLD.visible_to_student
       and NEW.source_table is not distinct from OLD.source_table
       and NEW.source_id is not distinct from OLD.source_id
       and NEW.type is not distinct from OLD.type
       and NEW.student_id is not distinct from OLD.student_id then
      return NEW;
    end if;
  end if;
  if NEW.visible_to_student and v_activity then
    if NEW.source_id is null or
       (NEW.source_table is distinct from 'activity_assignments' and NEW.type is distinct from 'activity') then
      raise exception 'Visible Activity mirror source cannot be cleared' using errcode = '42501';
    end if;
    select revoked_at, student_id into v_revoked, v_student
      from public.activity_assignments where id::text = NEW.source_id for share;
    if not found or v_revoked is not null or v_student is distinct from NEW.student_id then
      raise exception 'Activity mirror must name an available source for this student' using errcode = '42501';
    end if;
  end if;
  return NEW;
end;
$function$

